const TEMPLATE_IMAGES = {
    'modelo1.jpg': 'data:image/jpeg;base64,',
    'modelo2.jpg': 'data:image/jpeg;base64,'
};

// Sobrescrita global do fabric.Image.fromURL para interceptar imagens locais e carregar em Base64
const originalFromURL = fabric.Image.fromURL;
fabric.Image.fromURL = function(url, callback, imgOptions) {
    let targetUrl = url;
    if (typeof TEMPLATE_IMAGES !== 'undefined' && TEMPLATE_IMAGES[url]) {
        targetUrl = TEMPLATE_IMAGES[url];
    }
    return originalFromURL.call(fabric.Image, targetUrl, callback, imgOptions);
};


// ==========================================
// CONFIGURAÃ‡Ã•ES GERAIS E MATEMÃTICA
// ==========================================



const DPI = 400;

// FunÃ§Ã£o de conversÃ£o real mm para pixels baseada no DPI
function mmToPx(mm) {
    return (mm / 25.4) * DPI;
}

// FunÃ§Ã£o de conversÃ£o inversa: pixels para mm
function pxToMm(px) {
    return (px / DPI) * 25.4;
}

// ConfiguraÃ§Ãµes do Documento (PadrÃ£o: 218x20mm)
const paperWidthMM = 218;
const paperHeightMM = 20;
const bleedMM = 0;       // Sangria zerada a pedido do usuÃ¡rio
const safeMarginMM = 5;  // Margem de SeguranÃ§a Interna

// Calculando pixels
const totalWidthPx = mmToPx(paperWidthMM + (bleedMM * 2));
const totalHeightPx = mmToPx(paperHeightMM + (bleedMM * 2));

const cutXPx = mmToPx(bleedMM);
const cutYPx = mmToPx(bleedMM);
const cutWidthPx = mmToPx(paperWidthMM);
const cutHeightPx = mmToPx(paperHeightMM);

const safeXPx = mmToPx(bleedMM + safeMarginMM);
const safeYPx = mmToPx(bleedMM + safeMarginMM);
const safeWidthPx = mmToPx(paperWidthMM - (safeMarginMM * 2));
const safeHeightPx = mmToPx(paperHeightMM - (safeMarginMM * 2));

// ==========================================
// INICIALIZAÃ‡ÃƒO DO FABRIC.JS
// ==========================================

// Seleciona o elemento canvas do HTML
const canvasElement = document.getElementById('main-canvas');

// Ajusta o tamanho do Canvas HTML interno antes do Fabric inicializar
canvasElement.width = totalWidthPx;
canvasElement.height = totalHeightPx;

// Inicializa a instância do Fabric
const canvas = new fabric.Canvas('main-canvas', {
    width: totalWidthPx,
    height: totalHeightPx,
    backgroundColor: '#ffffff', // Fundo branco representando a página real + sangria
    preserveObjectStacking: true, // Garante que a seleção de objetos respeita o Z-Index
    selection: true // Permite arrastar para selecionar vários
});

// Força que todas as imagens carregadas no canvas (inclusive via loadFromJSON) usem CORS anonymous por padrão
fabric.Image.prototype.crossOrigin = 'anonymous';

// Ajuste visual na interface para caber na tela sem ser gigante 
// (Zoom out visual apenas via CSS transform, mantendo a resoluÃ§Ã£o do canvas intacta)
function fitCanvasToScreen() {
    const scrollArea = document.querySelector('.canvas-scroll-area');
    const editorWrapper = document.querySelector('.canvas-editor-wrapper');
    
    if (scrollArea && editorWrapper) {
        // Pega a largura livre do espaÃ§o central (menos 60px de padding lateral: 30px cada lado)
        // A largura total necessÃ¡ria Ã© a largura do canvas + largura do painel de nomes (305px)
        const totalNeededWidth = totalWidthPx + 305;
        const availableWidth = scrollArea.clientWidth - 60;
        
        // Calcula qual deve ser a escala para maximizar preenchendo a tela
        const scale = availableWidth / totalNeededWidth;
        
        editorWrapper.style.transform = `scale(${scale})`;
        editorWrapper.style.transformOrigin = 'top left';
    }
}

// Roda o cÃ¡lculo agora e sempre que a janela for redimensionada
fitCanvasToScreen();
window.addEventListener('resize', fitCanvasToScreen);

// ==========================================
// DESENHO DAS GUIAS OBRIGATÃ“RIAS
// ==========================================

// 1. Linha de Corte (O tamanho real do papel final)
const cutLine = new fabric.Rect({
    id: 'cutLine',
    left: cutXPx,
    top: cutYPx,
    width: cutWidthPx,
    height: cutHeightPx,
    fill: 'transparent',
    stroke: 'rgba(0,0,0,0.3)', // Preto semi-transparente
    strokeWidth: mmToPx(0.3), // Espessura fina
    selectable: false, // NÃ£o pode ser selecionada pelo usuÃ¡rio
    evented: false     // Ignora cliques
});

// 2. Margem de SeguranÃ§a (Tracejada vermelha) - Oculta a pedido do usuÃ¡rio
const safeLine = new fabric.Rect({
    id: 'safeLine',
    left: safeXPx,
    top: safeYPx,
    width: safeWidthPx,
    height: safeHeightPx,
    fill: 'transparent',
    stroke: 'rgba(239, 68, 68, 0.6)', // Vermelho claro
    strokeWidth: mmToPx(0.3),
    strokeDashArray: [mmToPx(2), mmToPx(2)], // Efeito tracejado
    selectable: false,
    evented: false,
    visible: false // Oculto para eliminar a marcaÃ§Ã£o pontilhada
});

// Adicionamos as guias ao canvas
canvas.add(cutLine, safeLine);

// Log para debug
console.log("Canvas Inicializado com sucesso!");
console.log(`DimensÃµes totais (px): ${totalWidthPx}x${totalHeightPx} a ${DPI} DPI`);

// ==========================================
// SISTEMA DE CANVAS CONTÃNUO (MULTIPLAS PÃGINAS)
// ==========================================
let pagesCount = 1;
const PAGE_GAP_PX = 40; // EspaÃ§amento visual entre pÃ¡ginas no canvas

document.getElementById('btn-duplicate-page').addEventListener('click', () => {
    try {
        pagesCount++;
        if (!window.pageNames) window.pageNames = [];
        window.pageNames.push("");
        updatePageNamesUI();
        
        // Aumenta a altura real do Canvas considerando o espaÃ§amento
        canvas.setHeight((totalHeightPx * pagesCount) + (PAGE_GAP_PX * (pagesCount - 1)));
        
        // FunÃ§Ã£o para pegar o centro matemÃ¡tico do objeto
        const getCenterY = (o) => {
            const bound = o.getBoundingRect();
            return bound.top + (bound.height / 2);
        };
        
        // Pega todos os objetos que pertencem Ã  "Primeira PÃ¡gina"
        const objectsToClone = canvas.getObjects().filter(obj => getCenterY(obj) < (totalHeightPx + (PAGE_GAP_PX/2)));
        
        // Deslocamento Y para a nova pÃ¡gina (Altura + Gap)
        const yOffset = (totalHeightPx + PAGE_GAP_PX) * (pagesCount - 1);
        
        // Clonar objetos (menos as guias globais originais)
        objectsToClone.forEach(obj => {
            if (obj === cutLine || obj === safeLine) return;
            if (obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine'))) return;
            
            obj.clone(function(clonedObj) {
                clonedObj.set({
                    top: clonedObj.top + yOffset,
                    evented: obj._isTemplate ? false : true, // Se for template, nÃ£o responde a eventos
                    selectable: obj._isTemplate ? false : true, // Se for template, nÃ£o pode ser selecionado
                    id: obj.id ? obj.id + '_p' + pagesCount : undefined
                });
                
                // Se for um template base, garante que ele continue com a marcaÃ§Ã£o
                if (obj._isTemplate) {
                    clonedObj.set({
                        _isTemplate: true
                    });
                }
                
                canvas.add(clonedObj);
            });
        });
    
    // Recria as guias visuais para a nova pÃ¡gina (combinando exatamente com os estilos originais)
    const newCutLine = new fabric.Rect({
        id: 'cutLine_p' + pagesCount,
        left: mmToPx(bleedMM),
        top: mmToPx(bleedMM) + yOffset,
        width: mmToPx(paperWidthMM),
        height: mmToPx(paperHeightMM),
        fill: 'transparent',
        stroke: 'rgba(0,0,0,0.3)', // Igual ao original
        strokeWidth: mmToPx(0.3),
        selectable: false,
        evented: false
    });
    
    const newSafeLine = new fabric.Rect({
        id: 'safeLine_p' + pagesCount,
        left: mmToPx(bleedMM + safeMarginMM),
        top: mmToPx(bleedMM + safeMarginMM) + yOffset,
        width: mmToPx(paperWidthMM - (safeMarginMM*2)),
        height: mmToPx(paperHeightMM - (safeMarginMM*2)),
        fill: 'transparent',
        stroke: 'rgba(239, 68, 68, 0.6)', // Igual ao original
        strokeWidth: mmToPx(0.3),
        strokeDashArray: [mmToPx(2), mmToPx(2)],
        selectable: false,
        evented: false,
        visible: false // Oculto conforme a regra anterior
    });
    
    canvas.add(newCutLine, newSafeLine);
    canvas.bringToFront(newCutLine);
    canvas.bringToFront(newSafeLine);
    
    // Garante que o canvas atualize
    canvas.requestRenderAll();
    
        // Desce a barra de rolagem suavemente para ver a nova pÃ¡gina
        const scrollArea = document.querySelector('.canvas-scroll-area');
        setTimeout(() => {
            if(scrollArea) {
                scrollArea.scrollTo({
                    top: scrollArea.scrollHeight,
                    behavior: 'smooth'
                });
            }
        }, 100);
        
        updateDeleteInput();
        selectPage(pagesCount); // Auto-seleciona a pÃ¡gina duplicada
        applyDefaultTemplateToPage(pagesCount); // Carrega o template base se a pÃ¡gina duplicada nÃ£o tiver template
    } catch(err) {
        alert("Erro no Duplicar: " + err.message);
        console.error(err);
    }
});

// Atualiza o estado do input de exclusÃ£o
function updateDeleteInput() {
    const delInput = document.getElementById('input-delete-page');
    const delBtn = document.getElementById('btn-delete-page');
    if (!delInput || !delBtn) return;
    
    delInput.max = pagesCount;
    if (pagesCount <= 1) {
        delInput.disabled = true;
        delBtn.disabled = true;
    } else {
        delInput.disabled = false;
        delBtn.disabled = false;
    }
}

// ==========================================
// ==========================================
// CONTROLE DOS NOMES DAS PÃGINAS E SELEÃ‡ÃƒO ATIVA
// ==========================================
window.selectedPageNumber = 1;
window.pageNames = [""];

function selectPage(pageNum) {
    if (pageNum < 1 || pageNum > pagesCount) return;
    window.selectedPageNumber = pageNum;
    
    // Sincroniza o seletor de templates para a pÃ¡gina ativa
    const inputTemplatePage = document.getElementById('input-template-page');
    if (inputTemplatePage) {
        inputTemplatePage.value = pageNum;
    }
    
    // Sincroniza o deletor de pÃ¡gina padrÃ£o para ser a selecionada (se for > 1)
    const delInput = document.getElementById('input-delete-page');
    if (delInput) {
        delInput.value = pageNum > 1 ? pageNum : Math.min(2, pagesCount);
    }
    
    // Atualiza o destaque visual no menu de nomes lateral
    const wrappers = document.querySelectorAll('.page-name-wrapper');
    wrappers.forEach((w, idx) => {
        if (idx + 1 === pageNum) {
            w.classList.add('selected');
        } else {
            w.classList.remove('selected');
        }
    });
    
    // Atualiza as bordas de corte no canvas
    highlightSelectedPageOnCanvas();
}

function highlightSelectedPageOnCanvas() {
    const objs = canvas.getObjects();
    objs.forEach(obj => {
        if (obj.id && obj.id.startsWith('cutLine')) {
            let pageOfLine = 1;
            if (obj.id.includes('_p')) {
                pageOfLine = parseInt(obj.id.split('_p')[1]);
            }
            
            if (pageOfLine === window.selectedPageNumber) {
                obj.set({
                    stroke: '#3b82f6', // Cor azul do acento
                    strokeWidth: mmToPx(0.6) // Mais grossa e destacada
                });
            } else {
                obj.set({
                    stroke: 'rgba(0,0,0,0.3)', // Cor padrÃ£o discreta
                    strokeWidth: mmToPx(0.3)
                });
            }
        }
    });
    canvas.requestRenderAll();
}

function getInsertionCoords() {
    const activePage = window.selectedPageNumber || 1;
    const pageTop = (activePage - 1) * (totalHeightPx + PAGE_GAP_PX);
    return {
        left: totalWidthPx / 2,
        top: pageTop + (totalHeightPx / 2)
    };
}

function updatePageNamesUI() {
    let container = document.getElementById('page-names-sidebar');
    if (!container) {
        container = document.createElement('div');
        container.id = 'page-names-sidebar';
        const editorWrapper = document.querySelector('.canvas-editor-wrapper');
        if (editorWrapper) {
            editorWrapper.appendChild(container);
        }
    }

    container.innerHTML = '';

    if (!window.pageNames) {
        window.pageNames = [];
    }

    // Garante que o array tenha o nÃºmero exato de pÃ¡ginas
    while (window.pageNames.length < pagesCount) {
        window.pageNames.push("");
    }
    if (window.pageNames.length > pagesCount) {
        window.pageNames = window.pageNames.slice(0, pagesCount);
    }

    // Cria as caixas de texto para cada pÃ¡gina
    for (let i = 0; i < pagesCount; i++) {
        const pageTop = i * (totalHeightPx + PAGE_GAP_PX);
        
        const wrapper = document.createElement('div');
        wrapper.className = 'page-name-wrapper';
        if (i + 1 === window.selectedPageNumber) {
            wrapper.classList.add('selected');
        }
        wrapper.style.top = `${pageTop + (totalHeightPx / 2) - 127}px`;
        
        // Clique no box seleciona a página
        wrapper.addEventListener('click', () => {
            selectPage(i + 1);
        });

        // Barra de Ações Rápidas (Rotação e Flip do Objeto Selecionado)
        const rotateFlipBar = document.createElement('div');
        rotateFlipBar.className = 'page-actions-bar';
        
        const btnRotLeft = document.createElement('button');
        btnRotLeft.className = 'action-icon-btn';
        btnRotLeft.innerHTML = '↺';
        btnRotLeft.title = 'Rotacionar 90° à Esquerda';
        btnRotLeft.addEventListener('click', (e) => {
            e.stopPropagation();
            rotateImage(90);
        });

        const btnRotRight = document.createElement('button');
        btnRotRight.className = 'action-icon-btn';
        btnRotRight.innerHTML = '↻';
        btnRotRight.title = 'Rotacionar 90° à Direita';
        btnRotRight.addEventListener('click', (e) => {
            e.stopPropagation();
            rotateImage(-90);
        });

        const btnFlipHorizontal = document.createElement('button');
        btnFlipHorizontal.className = 'action-icon-btn';
        btnFlipHorizontal.innerHTML = '↔';
        btnFlipHorizontal.title = 'Espelhar Horizontalmente';
        btnFlipHorizontal.addEventListener('click', (e) => {
            e.stopPropagation();
            flipImage(true);
        });

        const btnFlipVertical = document.createElement('button');
        btnFlipVertical.className = 'action-icon-btn';
        btnFlipVertical.innerHTML = '↕';
        btnFlipVertical.title = 'Espelhar Verticalmente';
        btnFlipVertical.addEventListener('click', (e) => {
            e.stopPropagation();
            flipImage(false);
        });

        rotateFlipBar.appendChild(btnRotLeft);
        rotateFlipBar.appendChild(btnRotRight);
        rotateFlipBar.appendChild(btnFlipHorizontal);
        rotateFlipBar.appendChild(btnFlipVertical);

        const label = document.createElement('label');
        label.innerText = `Nome da Pág. ${i + 1}`;

        const input = document.createElement('input');
        input.type = 'text';
        input.className = 'page-name-input';
        input.value = window.pageNames[i] || '';
        input.placeholder = `Pág. ${i + 1}`; // Placeholder limpo de 6 caracteres
        input.maxLength = 7; // Limita de 6 a 7 caracteres no máximo
        
        input.addEventListener('input', (e) => {
            window.pageNames[i] = e.target.value;
        });
        
        // Previne bolha de clique ao digitar para manter foco, mas ainda seleciona
        input.addEventListener('click', (e) => {
            e.stopPropagation();
            selectPage(i + 1);
        });

        wrapper.appendChild(rotateFlipBar);
        wrapper.appendChild(label);
        wrapper.appendChild(input);
        container.appendChild(wrapper);
    }
}
