// Eventos de Seleção para mostrar/esconder o painel de texto e atualizar valores
canvas.on('selection:created', updatePropertiesPanel);
canvas.on('selection:updated', updatePropertiesPanel);
canvas.on('selection:cleared', () => {
    textPropertiesPanel.style.display = 'none';
    if(shapePropertiesPanel) shapePropertiesPanel.style.display = 'none';
});

function updatePropertiesPanel(e) {
    const activeObj = e.selected ? e.selected[0] : canvas.getActiveObject();
    if (!activeObj) return;
    
    // Se for texto, mostra o painel e atualiza com os valores atuais do objeto
    if (activeObj.type === 'i-text' || activeObj.type === 'text') {
        textPropertiesPanel.style.display = 'block';
        if(shapePropertiesPanel) shapePropertiesPanel.style.display = 'none';
        
        const textContentInput = document.getElementById('prop-text-content');
        if (textContentInput) {
            textContentInput.value = activeObj.text || '';
        }
        
        document.getElementById('prop-font-family').value = activeObj.fontFamily;
        document.getElementById('prop-font-size').value = Math.round(activeObj.fontSize);
        document.getElementById('prop-font-color').value = activeObj.fill;
        
        // Formatações Negrito e Itálico
        const btnBold = document.getElementById('btn-bold');
        if (activeObj.fontWeight === 'bold') {
            btnBold.classList.add('active');
        } else {
            btnBold.classList.remove('active');
        }
        
        const btnItalic = document.getElementById('btn-italic');
        if (activeObj.fontStyle === 'italic') {
            btnItalic.classList.add('active');
        } else {
            btnItalic.classList.remove('active');
        }
        
        // Sublinhado
        const btnUnderline = document.getElementById('btn-underline');
        if (btnUnderline) {
            if (activeObj.underline) {
                btnUnderline.classList.add('active');
            } else {
                btnUnderline.classList.remove('active');
            }
        }
        
        // Alinhamento
        const alignLeft = document.getElementById('btn-align-left');
        const alignCenter = document.getElementById('btn-align-center');
        const alignRight = document.getElementById('btn-align-right');
        
        if (alignLeft && alignCenter && alignRight) {
            alignLeft.classList.remove('active');
            alignCenter.classList.remove('active');
            alignRight.classList.remove('active');
            
            if (activeObj.textAlign === 'left') alignLeft.classList.add('active');
            else if (activeObj.textAlign === 'center') alignCenter.classList.add('active');
            else if (activeObj.textAlign === 'right') alignRight.classList.add('active');
        }
        
        // Espaçamentos
        const lineHeightInput = document.getElementById('prop-line-height');
        if (lineHeightInput) {
            lineHeightInput.value = activeObj.lineHeight || 1.1;
        }
        
        const charSpacingInput = document.getElementById('prop-char-spacing');
        if (charSpacingInput) {
            charSpacingInput.value = activeObj.charSpacing || 0;
        }
    } else if (activeObj.type === 'rect' || activeObj.type === 'circle') {
        // Se for forma geométrica
        textPropertiesPanel.style.display = 'none';
        if(shapePropertiesPanel) {
            shapePropertiesPanel.style.display = 'block';
            shapeColorInput.value = activeObj.fill;
        }
    } else {
        textPropertiesPanel.style.display = 'none';
        if(shapePropertiesPanel) shapePropertiesPanel.style.display = 'none';
    }
}

