function setTextAlign(alignment) {
    const activeObj = canvas.getActiveObject();
    if (activeObj && (activeObj.type === 'i-text' || activeObj.type === 'text')) {
        activeObj.set('textAlign', alignment);
        
        btnAlignLeft.classList.remove('active');
        btnAlignCenter.classList.remove('active');
        btnAlignRight.classList.remove('active');
        
        if (alignment === 'left') btnAlignLeft.classList.add('active');
        else if (alignment === 'center') btnAlignCenter.classList.add('active');
        else if (alignment === 'right') btnAlignRight.classList.add('active');
        
        canvas.requestRenderAll();
        saveHistory();
    }
}

