// EXPORTAÃ‡ÃƒO IMAGENS (PNG e JPG) - Exporta todas as páginas do documento individualmente na pasta selecionada
async function downloadImage(format) {
    try {
        // Verifica se há suporte nativo para gravação em diretório (FileSystem Access API)
        if (typeof window.showDirectoryPicker === 'function') {
            // Solicita ao usuário a seleção da pasta de destino
            const dirHandle = await window.showDirectoryPicker({
                mode: 'readwrite'
            });
            
            // Loop por todas as páginas do documento
            for (let i = 0; i < pagesCount; i++) {
                const pageTop = i * (totalHeightPx + PAGE_GAP_PX);
                
                // Rastreamento de visibilidade das guias e templates
                const visibilityStates = [];
                canvas.getObjects().forEach(obj => {
                    const isGuide = obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine'));
                    const isTemplate = obj._isTemplate;
                    if (isGuide || isTemplate) {
                        visibilityStates.push({ obj: obj, wasVisible: obj.visible });
                        obj.set('visible', false);
                    }
                });
                
                // Trata o fundo do JPG (para não ficar transparente/preto)
                const originalBg = canvas.backgroundColor;
                if (format === 'jpeg') {
                    canvas.backgroundColor = '#ffffff';
                }
                canvas.requestRenderAll();
                
                // Gera a imagem da página específica
                const dataUrl = canvas.toDataURL({
                    format: format,
                    quality: 1,
                    multiplier: 1,
                    left: 0,
                    top: pageTop,
                    width: totalWidthPx,
                    height: totalHeightPx
                });
                
                // Restaura o estado visual original
                visibilityStates.forEach(state => {
                    state.obj.set('visible', state.wasVisible);
                });
                canvas.backgroundColor = originalBg;
                canvas.requestRenderAll();
                
                // Cria o Blob a partir do dataURL
                const response = await fetch(dataUrl);
                const blob = await response.blob();
                
                // Determina o nome do arquivo individualizado com base no nome da página
                const pageName = window.pageNames[i];
                const cleanName = pageName && pageName.trim() ? pageName.trim().replace(/[^a-zA-Z0-9_\-]/g, '_') : `Pulseira_${i + 1}`;
                const ext = format === 'jpeg' ? 'jpg' : 'png';
                const filename = `${cleanName}.${ext}`;
                
                // Salva o arquivo na pasta de destino selecionada
                const fileHandle = await dirHandle.getFileHandle(filename, { create: true });
                const writable = await fileHandle.createWritable();
                await writable.write(blob);
                await writable.close();
            }
            
            alert(`Exportação concluída! Todas as ${pagesCount} páginas foram salvas na pasta selecionada.`);
            
        } else {
            // FALLBACK: Caso o navegador não ofereça suporte ao showDirectoryPicker (Safari/Firefox)
            alert("Seu navegador não oferece suporte para gravação direta em diretórios. As páginas serão baixadas individualmente na sua pasta padrão de Downloads.");
            
            for (let i = 0; i < pagesCount; i++) {
                const pageTop = i * (totalHeightPx + PAGE_GAP_PX);
                
                const visibilityStates = [];
                canvas.getObjects().forEach(obj => {
                    const isGuide = obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine'));
                    const isTemplate = obj._isTemplate;
                    if (isGuide || isTemplate) {
                        visibilityStates.push({ obj: obj, wasVisible: obj.visible });
                        obj.set('visible', false);
                    }
                });
                
                const originalBg = canvas.backgroundColor;
                if (format === 'jpeg') {
                    canvas.backgroundColor = '#ffffff';
                }
                canvas.requestRenderAll();
                
                const dataUrl = canvas.toDataURL({
                    format: format,
                    quality: 1,
                    multiplier: 1,
                    left: 0,
                    top: pageTop,
                    width: totalWidthPx,
                    height: totalHeightPx
                });
                
                visibilityStates.forEach(state => {
                    state.obj.set('visible', state.wasVisible);
                });
                canvas.backgroundColor = originalBg;
                canvas.requestRenderAll();
                
                const pageName = window.pageNames[i];
                const cleanName = pageName && pageName.trim() ? pageName.trim().replace(/[^a-zA-Z0-9_\-]/g, '_') : `Pulseira_${i + 1}`;
                const ext = format === 'jpeg' ? 'jpg' : 'png';
                const filename = `${cleanName}.${ext}`;
                
                const a = document.createElement('a');
                a.href = dataUrl;
                a.download = filename;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
            }
        }
    } catch (err) {
        // Ignora se o erro for apenas o cancelamento do diálogo pelo usuário
        if (err.name !== 'AbortError') {
            console.error("Erro na exportação de imagens:", err);
            alert("Erro ao exportar páginas: " + err.message + "\n\nSe houver erro de segurança, certifique-se de que não há imagens externas sem permissão de CORS carregadas.");
        }
    }
}

