inputProject.addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (!file) return;
    
    const reader = new FileReader();
    reader.onload = function(f) {
        try {
            const data = JSON.parse(f.target.result);
            
            let jsonToLoad = data;
            
            if (data.version === 3 && data.canvasData) {
                // Formato Canvas ContÃ­nuo
                pagesCount = data.pagesCount || 1;
                window.pageNames = data.pageNames || []; // Restaura os nomes das pÃ¡ginas
                window.galleryImages = data.galleryImages || []; // Restaura as imagens da galeria
                updateGalleryUI();
                
                // Restaura a paleta de cores se gravada no JSON do projeto
                if (data.colorPalette && Array.isArray(data.colorPalette)) {
                    window.colorPalette = data.colorPalette;
                    savePaletteToStorage();
                    renderColorPalette();
                }
                
                if (pagesCount > 1) {
                    canvas.setHeight((totalHeightPx * pagesCount) + (PAGE_GAP_PX * (pagesCount - 1)));
                } else {
                    canvas.setHeight(totalHeightPx);
                }
                jsonToLoad = data.canvasData;
            } else if (data.version === 2 && data.pages) {
                // Formato Array de PÃ¡ginas (abandonado). Carrega sÃ³ a primeira pÃ¡gina para nÃ£o perder tudo.
                pagesCount = 1;
                window.pageNames = ["Pulseira 1"];
                window.galleryImages = [];
                updateGalleryUI();
                canvas.setHeight(totalHeightPx);
                jsonToLoad = data.pages[0];
            } else {
                // Formato v1 ClÃ¡ssico
                pagesCount = 1;
                window.pageNames = ["Pulseira 1"];
                window.galleryImages = [];
                updateGalleryUI();
                canvas.setHeight(totalHeightPx);
                jsonToLoad = data;
            }
            
            canvas.loadFromJSON(jsonToLoad, function() {
                const objs = canvas.getObjects();
                const loadedCutLine = objs.find(o => o.id === 'cutLine');
                const loadedSafeLine = objs.find(o => o.id === 'safeLine');
                
                if(loadedCutLine) Object.assign(cutLine, loadedCutLine);
                if(loadedSafeLine) Object.assign(safeLine, loadedSafeLine);
                
                updatePageNamesUI(); // Atualiza a barra de nomes de pÃ¡ginas com os dados carregados
                selectPage(1); // Seleciona a primeira pÃ¡gina do projeto carregado
                canvas.requestRenderAll();
                
                // Limpa o histÃ³rico de desfazer e salva o novo estado carregado
                window.undoStack = [];
                saveHistory();
            });
        } catch(err) {
            alert("Erro ao ler o arquivo de projeto.");
        }
    };
    reader.readAsText(file);
});

// ==========================================
// IMPORTAR E MESCLAR OUTRO PROJETO (APENSAR PÃGINAS)
