function loadStudioImage(dataUrl, savedFilters = null) {
    geminiOriginalImage = new Image();
    geminiOriginalImage.crossOrigin = 'anonymous';
    geminiOriginalImage.onload = () => {
        // Redimensiona o canvas fÃ­sico para bater com a imagem original
        studioCanvas.width = geminiOriginalImage.width;
        studioCanvas.height = geminiOriginalImage.height;
        
        if (savedFilters) {
            // Restaura os filtros salvos originalmente
            geminiFilters = { ...savedFilters };
            updateSlidersUI();
        } else {
            // Reseta os filtros manuais para os padrÃµes
            resetStudioFilters();
        }
        
        // Abre o modal
        studioOverlay.style.display = 'flex';
        
        // Limpa mensagens anteriores e adiciona a inicial personalizada
        studioMessages.innerHTML = `
            <div class="chat-msg assistant">
                ${savedFilters ? 'OlÃ¡! Reabri a sua imagem da galeria. VocÃª pode continuar a ediÃ§Ã£o aplicando novos ajustes manuais ou conversando com o Gemini.' : 'OlÃ¡! Eu sou o Gemini, seu assistente de IA. Selecione uma aÃ§Ã£o rÃ¡pida acima ou digite instruÃ§Ãµes personalizadas para comeÃ§armos a editar sua imagem.'}
            </div>
        `;
        
        // Renderiza no canvas
        redrawGeminiCanvas();
    };
    geminiOriginalImage.src = dataUrl;
}

function redrawGeminiCanvas() {
    if (!geminiOriginalImage) return;
    
    // Redimensiona o canvas fÃ­sico para bater com o tamanho atual da imagem (IA ou original)
    studioCanvas.width = geminiOriginalImage.naturalWidth || geminiOriginalImage.width || 300;
    studioCanvas.height = geminiOriginalImage.naturalHeight || geminiOriginalImage.height || 300;
    
    studioCtx.clearRect(0, 0, studioCanvas.width, studioCanvas.height);
    studioCtx.drawImage(geminiOriginalImage, 0, 0);
    
    // Filtro CSS aplicado no elemento canvas para visualizaÃ§Ã£o em tempo real (incluindo sepia e hueRotate)
    studioCanvas.style.filter = `brightness(${geminiFilters.brightness}%) contrast(${geminiFilters.contrast}%) saturate(${geminiFilters.saturation}%) blur(${geminiFilters.blur}px) grayscale(${geminiFilters.grayscale}%) invert(${geminiFilters.invert}%) sepia(${geminiFilters.sepia}%) hue-rotate(${geminiFilters.hueRotate}deg)`;
}

function updateSlidersUI() {
    for (const key in sliders) {
        if (sliders[key]) {
            sliders[key].value = geminiFilters[key];
            let suffix = '%';
            if (key === 'blur') suffix = 'px';
            sliderVals[key].innerText = geminiFilters[key] + suffix;
        }
    }
}

function resetStudioFilters() {
    geminiFilters = {
        brightness: 100,
        contrast: 100,
        saturation: 100,
        blur: 0,
        grayscale: 0,
        invert: 0,
        sepia: 0,
        hueRotate: 0
    };
    updateSlidersUI();
    redrawGeminiCanvas();
}

