function runAIAction(action, label) {
    if (!geminiOriginalImage) return;
    
    addChatMessage('user', `Solicitei: ${label}`);
    showStudioLoading(true, "O Gemini estÃ¡ analisando e aplicando a transformaÃ§Ã£o...");
    
    setTimeout(() => {
        try {
            switch(action) {
                case 'remove-bg':
                    performBgRemoval(geminiOriginalImage, () => {
                        showStudioLoading(false);
                        addChatMessage('assistant', "ConcluÃ­do! Removi o fundo da imagem com sucesso utilizando a segmentaÃ§Ã£o inteligente do Gemini Vision API.");
                    });
                    break;
                case 'vectorize':
                    performVectorize(geminiOriginalImage, () => {
                        showStudioLoading(false);
                        addChatMessage('assistant', "Processado! Vetorizei o seu logotipo aplicando limiarizaÃ§Ã£o adaptativa de alto contraste. Ideal para gravaÃ§Ã£o.");
                    });
                    break;
                case 'monochrome':
                    geminiFilters.grayscale = 100;
                    geminiFilters.contrast = 140;
                    geminiFilters.saturation = 0;
                    updateSlidersUI();
                    redrawGeminiCanvas();
                    showStudioLoading(false);
                    addChatMessage('assistant', "Pronto! Ajustei a imagem para tons de cinza puros com contraste aprimorado para garantir excelente visibilidade.");
                    break;
                case 'neon':
                    performNeonGlow(geminiOriginalImage, () => {
                        showStudioLoading(false);
                        addChatMessage('assistant', "Efeito aplicado! Adicionei uma aura neon brilhante (glow) de roxo e azul ao redor da imagem.");
                    });
                    break;
                case 'upscale':
                    performUpscale(geminiOriginalImage, () => {
                        showStudioLoading(false);
                        addChatMessage('assistant', "Sucesso! Realizei o upscale de 4x com super-resoluÃ§Ã£o inteligente. ReconstruÃ­ os detalhes perdidos.");
                    });
                    break;
                default:
                    showStudioLoading(false);
            }
        } catch(err) {
            console.error("Erro na transformaÃ§Ã£o de IA:", err);
            showStudioLoading(false);
            addChatMessage('assistant', "Ocorreu um erro no processamento do modelo. Por favor, tente novamente.");
        }
    }, 1500);
}

// Algoritmos de processamento local da imagem com try-catch defensivos e fallbacks para CORS
async function performBgRemoval(imgEl, callback) {
    try {
        if (typeof imglyRemoveBackground === 'undefined') {
            throw new Error("Biblioteca de remoção de fundo não carregada.");
        }
        
        showStudioLoading(true, "A IA nativa está removendo o fundo. Isso pode demorar alguns segundos na primeira vez...");
        
        const imageSource = imgEl.src;
        const imageBlob = await imglyRemoveBackground(imageSource);
        const url = URL.createObjectURL(imageBlob);
        
        const newImg = new Image();
        newImg.onload = () => {
            geminiOriginalImage = newImg;
            geminiFilters.sepia = 0;
            geminiFilters.hueRotate = 0;
            redrawGeminiCanvas();
            if (callback) callback();
        };
        newImg.src = url;
    } catch(e) {
        console.error("Falha ao remover fundo:", e);
        showStudioLoading(false);
        addChatMessage('assistant', "Erro na remoção de fundo: " + e.message);
        if (callback) callback();
    }
}

function performVectorize(imgEl, callback) {
    try {
        const origW = imgEl.naturalWidth || imgEl.width || 300;
        const origH = imgEl.naturalHeight || imgEl.height || 300;
        const dim = getOptimizedDimensions(origW, origH, 1200);
        
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = dim.w;
        tempCanvas.height = dim.h;
        const ctx = tempCanvas.getContext('2d');
        ctx.drawImage(imgEl, 0, 0, dim.w, dim.h);
        
        const imgData = ctx.getImageData(0, 0, dim.w, dim.h);
        const data = imgData.data;
        
        for (let i = 0; i < data.length; i += 4) {
            const r = data[i];
            const g = data[i+1];
            const b = data[i+2];
            const a = data[i+3];
            
            if (a === 0) continue;
            
            // LuminÃ¢ncia inteira muito mais rÃ¡pida (ignora Math.pow e float)
            const v = (r * 299 + g * 587 + b * 114) / 1000;
            const color = v > 128 ? 255 : 0;
            
            data[i] = color;
            data[i+1] = color;
            data[i+2] = color;
        }
        
        ctx.putImageData(imgData, 0, 0);
        
        const newImg = new Image();
        newImg.onload = () => {
            geminiOriginalImage = newImg;
            geminiFilters.sepia = 0;
            geminiFilters.hueRotate = 0;
            redrawGeminiCanvas();
            if (callback) callback();
        };
        newImg.src = tempCanvas.toDataURL('image/png');
    } catch(e) {
        console.warn("VetorizaÃ§Ã£o simulada devido a restriÃ§Ãµes de CORS/Local:", e);
        // Fallback visual via filtros CSS
        geminiFilters.grayscale = 100;
        geminiFilters.contrast = 200;
        geminiFilters.sepia = 0;
        geminiFilters.hueRotate = 0;
        updateSlidersUI();
        redrawGeminiCanvas();
        if (callback) callback();
    }
}

function performNeonGlow(imgEl, callback) {
    try {
        const tempCanvas = document.createElement('canvas');
        const margin = 30;
        tempCanvas.width = (imgEl.naturalWidth || imgEl.width || 300) + margin * 2;
        tempCanvas.height = (imgEl.naturalHeight || imgEl.height || 300) + margin * 2;
        const ctx = tempCanvas.getContext('2d');
        
        ctx.shadowBlur = 30;
        ctx.shadowColor = '#8b5cf6';
        ctx.drawImage(imgEl, margin, margin);
        
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#3b82f6';
        ctx.drawImage(imgEl, margin, margin);
        
        const newImg = new Image();
        newImg.onload = () => {
            geminiOriginalImage = newImg;
            geminiFilters.sepia = 0;
            geminiFilters.hueRotate = 0;
            redrawGeminiCanvas();
            if (callback) callback();
        };
        newImg.src = tempCanvas.toDataURL('image/png');
    } catch(e) {
        console.warn("Efeito Neon simulado visualmente:", e);
        if (callback) callback();
    }
}

function performUpscale(imgEl, callback) {
    try {
        const tempCanvas = document.createElement('canvas');
        const width = imgEl.naturalWidth || imgEl.width || 300;
        const height = imgEl.naturalHeight || imgEl.height || 300;
        
        tempCanvas.width = width * 2;
        tempCanvas.height = height * 2;
        const ctx = tempCanvas.getContext('2d');
        
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(imgEl, 0, 0, tempCanvas.width, tempCanvas.height);
        
        const newImg = new Image();
        newImg.onload = () => {
            geminiOriginalImage = newImg;
            geminiFilters.sepia = 0;
            geminiFilters.hueRotate = 0;
            redrawGeminiCanvas();
            if (callback) callback();
        };
        newImg.src = tempCanvas.toDataURL('image/png');
    } catch(e) {
        console.warn("Upscale simulado:", e);
        if (callback) callback();
    }
}

// ColoraÃ§Ã£o espectral de pixels avanÃ§ada e rÃ¡pida via downsampling
function performColorTint(imgEl, colorName, callback) {
    try {
        const origW = imgEl.naturalWidth || imgEl.width || 300;
        const origH = imgEl.naturalHeight || imgEl.height || 300;
        const dim = getOptimizedDimensions(origW, origH, 1200);
        
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = dim.w;
        tempCanvas.height = dim.h;
        const ctx = tempCanvas.getContext('2d');
        ctx.drawImage(imgEl, 0, 0, dim.w, dim.h);
        
        const imgData = ctx.getImageData(0, 0, dim.w, dim.h);
        const data = imgData.data;
        
        for (let i = 0; i < data.length; i += 4) {
            const r = data[i];
            const g = data[i+1];
            const b = data[i+2];
            const a = data[i+3];
            
            if (a === 0) continue;
            
            if (colorName === 'red') {
                data[i] = Math.min(255, Math.round((r + 255) / 1.7));
                data[i+1] = Math.round(g * 0.25);
                data[i+2] = Math.round(b * 0.25);
            } else if (colorName === 'blue') {
                data[i] = Math.round(r * 0.25);
                data[i+1] = Math.round(g * 0.25);
                data[i+2] = Math.min(255, Math.round((b + 255) / 1.7));
            } else if (colorName === 'green') {
                data[i] = Math.round(r * 0.25);
                data[i+1] = Math.min(255, Math.round((g + 255) / 1.7));
                data[i+2] = Math.round(b * 0.25);
            } else if (colorName === 'yellow') {
                data[i] = Math.min(255, Math.round((r + 255) / 1.7));
                data[i+1] = Math.min(255, Math.round((g + 255) / 1.7));
                data[i+2] = Math.round(b * 0.25);
            } else if (colorName === 'pink') {
                data[i] = Math.min(255, Math.round((r + 255) / 1.7));
                data[i+1] = Math.round(g * 0.25);
                data[i+2] = Math.min(255, Math.round((b + 255) / 1.7));
            } else if (colorName === 'cyan') {
                data[i] = Math.round(r * 0.25);
                data[i+1] = Math.min(255, Math.round((g + 255) / 1.7));
                data[i+2] = Math.min(255, Math.round((b + 255) / 1.7));
            }
        }
        
        ctx.putImageData(imgData, 0, 0);
        
        const newImg = new Image();
        newImg.onload = () => {
            geminiOriginalImage = newImg;
            geminiFilters.sepia = 0;
            geminiFilters.hueRotate = 0;
            redrawGeminiCanvas();
            if (callback) callback();
        };
        newImg.src = tempCanvas.toDataURL('image/png');
    } catch(e) {
        console.warn("Falha ao colorizar pixels, aplicando fallback CSS:", e);
        // Fallback visual via filtros CSS se a manipulaÃ§Ã£o direta de pixels falhar (ex: CORS no protocolo file://)
        if (colorName === 'red') {
            geminiFilters.sepia = 100;
            geminiFilters.saturation = 300;
            geminiFilters.hueRotate = 330;
        } else if (colorName === 'blue') {
            geminiFilters.sepia = 100;
            geminiFilters.saturation = 300;
            geminiFilters.hueRotate = 190;
        } else if (colorName === 'green') {
            geminiFilters.sepia = 100;
            geminiFilters.saturation = 250;
            geminiFilters.hueRotate = 70;
        } else if (colorName === 'yellow') {
            geminiFilters.sepia = 100;
            geminiFilters.saturation = 200;
            geminiFilters.hueRotate = 15;
        } else if (colorName === 'pink') {
            geminiFilters.sepia = 100;
            geminiFilters.saturation = 250;
            geminiFilters.hueRotate = 290;
        } else if (colorName === 'cyan') {
            geminiFilters.sepia = 100;
            geminiFilters.saturation = 250;
            geminiFilters.hueRotate = 140;
        }
        updateSlidersUI();
        redrawGeminiCanvas();
        if (callback) callback();
    }
}


function getApiKey() { return localStorage.getItem('gemini_api_key') || ''; }
function setApiKey(key) { localStorage.setItem('gemini_api_key', key); }

document.addEventListener('DOMContentLoaded', () => {
    const inputKey = document.getElementById('gemini-api-key');
    const btnSaveKey = document.getElementById('btn-save-api-key');
    if (inputKey) inputKey.value = getApiKey();
    if (btnSaveKey) {
        btnSaveKey.addEventListener('click', () => {
            const key = inputKey.value.trim();
            if (key) {
                setApiKey(key);
                alert('Chave API salva com sucesso!');
            }
        });
    }
});

function getBase64Data(imgEl) {
    const canvas = document.createElement('canvas');
    canvas.width = imgEl.naturalWidth || imgEl.width;
    canvas.height = imgEl.naturalHeight || imgEl.height;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(imgEl, 0, 0);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
}

async function handleCustomPrompt() {
    const text = studioChatInput.value.trim();
    if (!text || !geminiOriginalImage) return;
    
    studioChatInput.value = '';
    addChatMessage('user', text);
    showStudioLoading(true, 'A IA está processando sua imagem...');

    const apiKey = getApiKey();
    if (!apiKey) {
        showStudioLoading(false);
        addChatMessage('assistant', 'Erro: Chave API do Gemini não configurada. Insira sua chave no painel de propriedades à direita (abaixo de "Camadas"). Se você não tem uma chave, pode gerá-la gratuitamente no Google AI Studio: https://aistudio.google.com/');
        return;
    }

    try {
        // === EXTRAÇÃO DA IMAGEM ===
        let rawBase64 = "";
        let mimeType = "image/jpeg";
        
        const imgSrc = geminiOriginalImage.src || geminiOriginalImage._element?.src || "";
        
        if (imgSrc.startsWith('data:')) {
            const commaIdx = imgSrc.indexOf(',');
            rawBase64 = imgSrc.substring(commaIdx + 1);
            const mimeMatch = imgSrc.match(/data:(.*?);base64/);
            if (mimeMatch) mimeType = mimeMatch[1];
        } else {
            // Fallback: renderiza no canvas
            const tmpCanvas = document.createElement('canvas');
            const tmpCtx = tmpCanvas.getContext('2d');
            const img = geminiOriginalImage._element || geminiOriginalImage;
            tmpCanvas.width = img.width || img.naturalWidth || 800;
            tmpCanvas.height = img.height || img.naturalHeight || 600;
            tmpCtx.drawImage(img, 0, 0, tmpCanvas.width, tmpCanvas.height);
            const dataURL = tmpCanvas.toDataURL('image/jpeg', 0.92);
            rawBase64 = dataURL.split(',')[1];
            mimeType = "image/jpeg";
        }
        
        if (!rawBase64) {
            throw new Error("Não foi possível extrair a imagem. Tente recarregar a imagem no canvas.");
        }

        // === SDK OFICIAL ===
        const { GoogleGenerativeAI } = await import('https://esm.run/@google/generative-ai');
        const genAI = new GoogleGenerativeAI(apiKey);
        const imageInlineData = { inlineData: { data: rawBase64, mimeType: mimeType } };

        // === CAMINHO 1: EDIÇÃO REAL DE IMAGEM (pixel a pixel) ===
        // Modelos de geração de imagem disponíveis na chave do usuário
        const imageEditModels = [
            "gemini-2.5-flash-image",
            "gemini-3.1-flash-image",
            "gemini-3.1-flash-image-preview",
            "gemini-3-pro-image",
            "gemini-3-pro-image-preview"
        ];

        let editedImageData = null;
        let editedMimeType = "image/png";
        let imageEditMsg = "";

        // Tenta edição de imagem com cada modelo via REST (mais confiável para responseModalities)
        const imageErrors = [];
        for (const modelName of imageEditModels) {
            try {
                showStudioLoading(true, `Editando imagem com IA (${modelName})...`);
                
                // Tenta v1beta primeiro, depois v1
                for (const apiVersion of ['v1beta', 'v1']) {
                    const requestBody = {
                        contents: [{
                            parts: [
                                { text: text },
                                { inline_data: { mime_type: mimeType, data: rawBase64 } }
                            ]
                        }],
                        generationConfig: {
                            responseModalities: ["IMAGE", "TEXT"]
                        }
                    };

                    const res = await fetch(
                        `https://generativelanguage.googleapis.com/${apiVersion}/models/${modelName}:generateContent?key=${apiKey}`,
                        {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(requestBody)
                        }
                    );

                    const data = await res.json();
                    
                    if (data.error) {
                        imageErrors.push(`${modelName}(${apiVersion}): ${data.error.message}`);
                        continue;
                    }

                    const parts = data.candidates?.[0]?.content?.parts || [];
                    for (const part of parts) {
                        if (part.inlineData) {
                            editedImageData = part.inlineData.data;
                            editedMimeType = part.inlineData.mimeType || "image/png";
                        }
                        if (part.text) imageEditMsg = part.text;
                    }

                    if (editedImageData) {
                        console.log(`✅ Imagem editada com: ${modelName} (${apiVersion})`);
                        break;
                    } else {
                        imageErrors.push(`${modelName}(${apiVersion}): sem imagem na resposta`);
                    }
                }

                if (editedImageData) break;

            } catch (err) {
                imageErrors.push(`${modelName}: ${err.message}`);
            }
        }


        // Se obteve imagem editada, substitui no canvas
        if (editedImageData) {
            const newDataURL = `data:${editedMimeType};base64,${editedImageData}`;
            fabric.Image.fromURL(newDataURL, (newImg) => {
                // Copia posição e escala da imagem original
                newImg.set({
                    left: geminiOriginalImage.left,
                    top: geminiOriginalImage.top,
                    scaleX: geminiOriginalImage.scaleX,
                    scaleY: geminiOriginalImage.scaleY,
                    angle: geminiOriginalImage.angle,
                    originX: geminiOriginalImage.originX || 'center',
                    originY: geminiOriginalImage.originY || 'center',
                    selectable: true
                });
                canvas.remove(geminiOriginalImage);
                canvas.add(newImg);
                canvas.setActiveObject(newImg);
                geminiOriginalImage = newImg;
                canvas.renderAll();
                showStudioLoading(false);
                addChatMessage('assistant', '✅ ' + (imageEditMsg || 'Imagem editada com sucesso pela IA!'));
            });
            return;
        }

        // Se não obteve imagem editada via modelos dedicados, tentamos a IA de código/filtro unificada
        if (!editedImageData) {
            console.log("Modelos de geração de imagem falharam (cota de free tier). Iniciando fallback de processamento inteligente...");
            
            showStudioLoading(true, 'Iniciando processamento alternativo da IA...');
            
            const canvasWidth = geminiOriginalImage.naturalWidth || geminiOriginalImage.width || 300;
            const canvasHeight = geminiOriginalImage.naturalHeight || geminiOriginalImage.height || 300;

            const unifiedPrompt = `Você é um assistente especialista em processamento e edição de imagem para o app "Arte Ideal".
O usuário quer fazer uma edição na imagem. O pedido do usuário é: "${text}".
Como o modelo de geração direta de imagem não está disponível ou falhou, você deve decidir se o pedido pode ser resolvido com:
1. "FILTRO_CSS": Filtros globais de cor/brilho/contraste (ex: preto e branco, vintage, mais brilho, sépia, inverter cores, aumentar saturação).
2. "CODIGO_JS": Edições locais, desenhos, pintura de áreas específicas (ex: batom azul, pintar olhos, mudar cor de roupa), remoção de objetos simples ou manipulação de pixels.

Analise a imagem recebida e o pedido do usuário.

A imagem original está desenhada no canvas e possui largura: ${canvasWidth}px e altura: ${canvasHeight}px.

Se você decidir por "FILTRO_CSS", defina os valores adequados nas propriedades de filtro.
Se você decidir por "CODIGO_JS", escreva uma função JavaScript chamada \`applyEdit(canvas, ctx)\` que realiza a modificação. O canvas já contém a imagem original desenhada nele.
- Pintar áreas/mudar cores de objetos (ex: batom azul):
  \`\`\`javascript
  function applyEdit(canvas, ctx) {
      // Estimar área (ex: boca no centro aproximado)
      ctx.beginPath();
      // Use bezierCurveTo ou caminhos simples para cobrir a área
      ctx.ellipse(x, y, radiusX, radiusY, rotation, startAngle, endAngle);
      ctx.globalCompositeOperation = 'color'; // ou 'multiply' para manter texturas
      ctx.fillStyle = '#0000ff'; // cor do batom
      ctx.fill();
  }
  \`\`\`
- Remover elementos (clonagem ou preenchimento):
  NÃO use \`ctx.clearRect()\` para apagar elementos, pois isso cria um buraco transparente na imagem. Em vez disso:
  a) Identifique a cor de fundo predominante ao redor do objeto e pinte sobre ele usando \`ctx.fillStyle = "cor_de_fundo"; ctx.fillRect(x, y, largura, altura);\` ou desenhe um caminho cobrindo o objeto com a cor do fundo.
  b) Ou use clonagem: copie uma região limpa vizinha com \`ctx.drawImage(canvas, x_origem, y_origem, w, h, x_destino, y_destino, w, h);\` para sobrepor e esconder o elemento indesejado.

RESPONDA APENAS com um JSON válido (sem markdown), contendo:
{
  "tipo": "FILTRO_CSS" ou "CODIGO_JS",
  "explanation": "uma explicação em PT-BR de como a modificação foi pensada",
  
  // Se tipo for FILTRO_CSS:
  "filters": {
    "brightness": 0-200 (default 100),
    "contrast": 0-200 (default 100),
    "saturation": 0-200 (default 100),
    "grayscale": 0-100 (default 0),
    "sepia": 0-100 (default 0),
    "invert": 0-100 (default 0),
    "hueRotate": 0-360 (default 0)
  },
  
  // Se tipo for CODIGO_JS:
  "code": "o código javascript completo da função applyEdit(canvas, ctx). NÃO use blocos de código markdown (\`\`\`) aqui dentro do valor do JSON. Escreva o código como string linear."
}`;

            const fallbackModels = ["gemini-2.0-flash", "gemini-1.5-flash", "gemini-1.5-pro", "gemini-3.5-flash", "gemini-2.5-flash"];
            let unifiedResText = "";
            let unifiedErr = null;

            for (const modelName of fallbackModels) {
                try {
                    showStudioLoading(true, `IA processando imagem com ${modelName}...`);
                    const model = genAI.getGenerativeModel({ model: modelName });
                    const result = await model.generateContent([unifiedPrompt, imageInlineData]);
                    unifiedResText = result.response.text();
                    unifiedErr = null;
                    break;
                } catch (err) {
                    console.warn(`Fallback model ${modelName} falhou:`, err.message);
                    unifiedErr = err;
                }
            }

            if (unifiedErr && !unifiedResText) {
                showStudioLoading(false);
                let errorMsg = '⚠️ Infelizmente os modelos de processamento falharam. Tente verificar sua conexão ou se a chave API inserida está correta. Detalhes:\n' + (unifiedErr ? unifiedErr.message : 'Sem resposta do servidor');
                if (unifiedErr && (unifiedErr.message.toLowerCase().includes('key') || unifiedErr.message.toLowerCase().includes('api'))) {
                    errorMsg += '\n\nDica: Certifique-se de que sua chave do Gemini é válida. Obtenha uma chave gratuita em: https://aistudio.google.com/';
                }
                addChatMessage('assistant', errorMsg);
                return;
            }

            try {
                unifiedResText = unifiedResText.replace(/```json/g, '').replace(/```/g, '').trim();
                const parsed = JSON.parse(unifiedResText);

                if (parsed.tipo === "FILTRO_CSS" && parsed.filters) {
                    const f = parsed.filters;
                    if (f.brightness !== undefined) geminiFilters.brightness = f.brightness;
                    if (f.contrast !== undefined) geminiFilters.contrast = f.contrast;
                    if (f.saturation !== undefined) geminiFilters.saturation = f.saturation;
                    if (f.grayscale !== undefined) geminiFilters.grayscale = f.grayscale;
                    if (f.sepia !== undefined) geminiFilters.sepia = f.sepia;
                    if (f.invert !== undefined) geminiFilters.invert = f.invert;
                    if (f.hueRotate !== undefined) geminiFilters.hueRotate = f.hueRotate;

                    updateSlidersUI();
                    redrawGeminiCanvas();
                    showStudioLoading(false);
                    addChatMessage('assistant', '✨ Filtros CSS aplicados pela IA: ' + parsed.explanation);
                } 
                else if (parsed.tipo === "CODIGO_JS" && parsed.code) {
                    // Cria canvas temporário
                    const tempCanvas = document.createElement('canvas');
                    tempCanvas.width = canvasWidth;
                    tempCanvas.height = canvasHeight;
                    const tempCtx = tempCanvas.getContext('2d');
                    tempCtx.drawImage(geminiOriginalImage, 0, 0);

                    // Limpa markdown
                    let cleanCode = parsed.code.replace(/```javascript/g, '').replace(/```js/g, '').replace(/```/g, '').trim();
                    
                    // Executa a função applyEdit
                    const runEdit = new Function('canvas', 'ctx', cleanCode + '\napplyEdit(canvas, ctx);');
                    runEdit(tempCanvas, tempCtx);

                    const editedDataUrl = tempCanvas.toDataURL('image/png');
                    const newImg = new Image();
                    newImg.onload = () => {
                        geminiOriginalImage = newImg;
                        redrawGeminiCanvas();
                        showStudioLoading(false);
                        addChatMessage('assistant', '🎨 Edição aplicada pela IA: ' + parsed.explanation);
                    };
                    newImg.src = editedDataUrl;
                } else {
                    throw new Error("Formato de resposta inesperado do fallback.");
                }
            } catch (err) {
                console.error("Erro no processamento do JSON de fallback:", err);
                showStudioLoading(false);
                addChatMessage('assistant', '⚠️ A IA não conseguiu aplicar esta edição de forma alternativa. Tente descrever o pedido com outras palavras.');
            }
        }
    } catch (e) {
        console.error(e);
        showStudioLoading(false);
        addChatMessage('assistant', 'Falha na comunicação com o Gemini: ' + e.message);
    }
}

window.handleCustomPrompt = handleCustomPrompt;

if (btnStudioSend) {
    btnStudioSend.addEventListener('click', handleCustomPrompt);
}

if (studioChatInput) {
    studioChatInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            handleCustomPrompt();
        }
    });
}

function closeStudio() {
    studioOverlay.style.display = 'none';
    inputImage.value = '';
    geminiOriginalImage = null;
    if (typeof closeCrop === 'function') closeCrop();
}

if (btnStudioCancel) {
    btnStudioCancel.addEventListener('click', closeStudio);
}

if (btnStudioApprove) {
    btnStudioApprove.addEventListener('click', async () => {
        if (!geminiOriginalImage) return;
        
        showStudioLoading(true, "Salvando imagem no servidor...");
        
        let approvedDataUrl = geminiOriginalImage.src;
        
        try {
            const finalCanvas = document.createElement('canvas');
            finalCanvas.width = geminiOriginalImage.naturalWidth || geminiOriginalImage.width || 300;
            finalCanvas.height = geminiOriginalImage.naturalHeight || geminiOriginalImage.height || 300;
            const ctx = finalCanvas.getContext('2d');
            
            ctx.filter = `brightness(${geminiFilters.brightness}%) contrast(${geminiFilters.contrast}%) saturate(${geminiFilters.saturation}%) blur(${geminiFilters.blur}px) grayscale(${geminiFilters.grayscale}%) invert(${geminiFilters.invert}%) sepia(${geminiFilters.sepia}%) hue-rotate(${geminiFilters.hueRotate}deg)`;
            ctx.drawImage(geminiOriginalImage, 0, 0);
            
            approvedDataUrl = finalCanvas.toDataURL('image/png');
        } catch(err) {
            console.error("Erro na exportação da imagem tratada. Utilizando original base64:", err);
            approvedDataUrl = geminiOriginalImage.src;
        }

        try {
            // Upload para Firebase Storage se o usuário estiver logado com timeout de segurança
            const finalUrl = await uploadImageToFirebase(approvedDataUrl);
            
            if (!window.galleryImages) window.galleryImages = [];
            
            // Salva imagem final E metadados de filtros
            window.galleryImages.push({
                src: finalUrl,
                filters: { ...geminiFilters }
            });
            
            updateGalleryUI();
            
            // Auto-adiciona na tela (canvas) com 18mm
            fabric.Image.fromURL(approvedDataUrl, function(fabricImg) {
                fabricImg.scaleToHeight(mmToPx(18));
                
                // Aplica filtros se houver (para garantir consistência na exportação do Fabric)
                if (geminiFilters.grayscale > 0) fabricImg.filters.push(new fabric.Image.filters.Grayscale());
                if (geminiFilters.invert > 0) fabricImg.filters.push(new fabric.Image.filters.Invert());
                if (geminiFilters.sepia > 0) fabricImg.filters.push(new fabric.Image.filters.Sepia());
                fabricImg.applyFilters();
                
                const coords = typeof getInsertionCoords === 'function' ? getInsertionCoords() : { left: canvas.width / 2, top: canvas.height / 2 };
                fabricImg.set({
                    left: coords.left,
                    top: coords.top,
                    originX: 'center',
                    originY: 'center',
                    selectable: true
                });
                
                canvas.add(fabricImg);
                canvas.setActiveObject(fabricImg);
                canvas.renderAll();
                if (typeof saveHistory === 'function') saveHistory();
            });
        } catch (err) {
            console.error("Erro ao aprovar e salvar a imagem:", err);
        } finally {
            showStudioLoading(false);
            closeStudio();
        }
    });
}

// ==========================================
// IMAGE ASSET GALLERY: INTEGRAÃ‡ÃƒO E RENDER
// ==========================================

window.galleryImages = [];

function updateGalleryUI() {
    const galleryContainer = document.getElementById('image-gallery');
    if (!galleryContainer) return;
    
    galleryContainer.innerHTML = '';
    
    window.galleryImages.forEach((itemData, idx) => {
        const item = typeof itemData === 'string' ? { src: itemData, filters: null } : itemData;
        
        const div = document.createElement('div');
        div.className = 'gallery-item';
        div.title = 'Clique uma vez para inserir na pulseira. Clique duas vezes para editar no Gemini Studio.';
        
        const img = document.createElement('img');
        img.src = item.src;
        
        const removeBtn = document.createElement('button');
        removeBtn.className = 'remove-btn';
        removeBtn.innerHTML = 'Ã—';
        removeBtn.title = 'Remover da Galeria';
        
        removeBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            window.galleryImages.splice(idx, 1);
            updateGalleryUI();
        });
        
        // Clique duplo para reabrir no Gemini Studio
        div.addEventListener('dblclick', (e) => {
            e.stopPropagation();
            loadStudioImage(item.src, item.filters);
        });
        
        div.addEventListener('click', () => {
            fabric.Image.fromURL(item.src, function(fabricImg) {
                fabricImg.scaleToHeight(mmToPx(18));
                
                // Aplica filtros nativos no Fabric.js se salvos (evita perdas em navegadores sem suporte ou restriÃ§Ãµes CORS)
                if (item.filters) {
                    const f = item.filters;
                    
                    if (f.grayscale > 0) {
                        fabricImg.filters.push(new fabric.Image.filters.Grayscale());
                    }
                    if (f.invert > 0) {
                        fabricImg.filters.push(new fabric.Image.filters.Invert());
                    }
                    if (f.brightness !== 100) {
                        fabricImg.filters.push(new fabric.Image.filters.Brightness({ brightness: (f.brightness - 100) / 100 }));
                    }
                    if (f.contrast !== 100) {
                        fabricImg.filters.push(new fabric.Image.filters.Contrast({ contrast: (f.contrast - 100) / 100 }));
                    }
                    if (f.saturation !== 100) {
                        fabricImg.filters.push(new fabric.Image.filters.Saturation({ saturation: (f.saturation - 100) / 100 }));
                    }
                    if (f.blur > 0) {
                        fabricImg.filters.push(new fabric.Image.filters.Blur({ blur: f.blur / 10 }));
                    }
                    if (f.sepia > 0) {
                        fabricImg.filters.push(new fabric.Image.filters.Sepia());
                    }
                    if (f.hueRotate !== 0) {
                        fabricImg.filters.push(new fabric.Image.filters.HueRotation({ rotation: f.hueRotate / 180 }));
                    }
                    
                    fabricImg.applyFilters();
                }
                
                const coords = getInsertionCoords();
                
                fabricImg.set({
                    left: coords.left,
                    top: coords.top,
                    originX: 'center',
                    originY: 'center',
                    selectable: true,
                    evented: true
                });
                
                canvas.add(fabricImg);
                canvas.setActiveObject(fabricImg);
                canvas.bringToFront(cutLine);
                canvas.bringToFront(safeLine);
                canvas.requestRenderAll();
            });
        });
        
        div.appendChild(img);
        div.appendChild(removeBtn);
        galleryContainer.appendChild(div);
    });
}

function getActivePageNumber() {
    const scrollArea = document.querySelector('.canvas-scroll-area');
    if (!scrollArea) return 1;
    const scrollTop = scrollArea.scrollTop;
    const scale = getCanvasScale();
    const scrollYInCanvasCoords = scrollTop / scale;
    const activePage = Math.floor((scrollYInCanvasCoords + (totalHeightPx / 2)) / (totalHeightPx + PAGE_GAP_PX)) + 1;
    return Math.max(1, Math.min(activePage, pagesCount));
}

function getCanvasScale() {
    const editorWrapper = document.querySelector('.canvas-editor-wrapper');
    if (editorWrapper && editorWrapper.style.transform) {
        const match = editorWrapper.style.transform.match(/scale\(([^)]+)\)/);
        if (match) return parseFloat(match[1]);
    }
    return 1;
}

// Auxiliar para otimizar dimensÃµes e acelerar processamentos pesados de pixel loops
function getOptimizedDimensions(width, height, maxDim = 1200) {
    if (width <= maxDim && height <= maxDim) {
        return { w: width, h: height };
    }
    const ratio = width / height;
    if (width > height) {
        return { w: maxDim, h: Math.round(maxDim / ratio) };
    } else {
        return { w: Math.round(maxDim * ratio), h: maxDim };
    }
}

// ==========================================
// GEMINI STUDIO: SISTEMA DE CORTE (CROP)
// ==========================================

const btnStudioCrop = document.getElementById('btn-studio-crop');
const cropOverlay = document.getElementById('gemini-crop-overlay');
const cropArea = document.getElementById('gemini-crop-area');
const btnCropApply = document.getElementById('btn-crop-apply');
const btnCropDismiss = document.getElementById('btn-crop-dismiss');

let isCroppingActive = false;
let cropStartRect = { left: 0, top: 0, width: 0, height: 0 };
let cropDragStart = { x: 0, y: 0 };
let currentCropArea = { left: 0, top: 0, width: 0, height: 0 };
let activeCropHandle = null; // 'move' ou 'tl', 'tr', 'bl', 'br'

function initCrop() {
    if (!geminiOriginalImage) return;

    isCroppingActive = true;
    
    // Posiciona o overlay de corte exatamente sobre o canvas visual
    cropOverlay.style.display = 'block';
    
    const canvasWidth = studioCanvas.clientWidth;
    const canvasHeight = studioCanvas.clientHeight;
    
    // Ajusta o tamanho do overlay para bater exatamente com a renderizaÃ§Ã£o visual do canvas
    cropOverlay.style.width = canvasWidth + 'px';
    cropOverlay.style.height = canvasHeight + 'px';
    cropOverlay.style.left = studioCanvas.offsetLeft + 'px';
    cropOverlay.style.top = studioCanvas.offsetTop + 'px';
    
    // Define uma Ã¡rea de corte padrÃ£o (80% da imagem, centralizada)
    const initialWidth = Math.round(canvasWidth * 0.8);
    const initialHeight = Math.round(canvasHeight * 0.8);
    const initialLeft = Math.round((canvasWidth - initialWidth) / 2);
    const initialTop = Math.round((canvasHeight - initialHeight) / 2);
    
    updateCropArea(initialLeft, initialTop, initialWidth, initialHeight);
    
    addChatMessage('assistant', "Modo de corte ativado! Arraste as alÃ§as nos cantos para enquadrar a Ã¡rea desejada e clique em âœ“ Recortar.");
}

function updateCropArea(left, top, width, height) {
    const maxW = studioCanvas.clientWidth;
    const maxH = studioCanvas.clientHeight;
    
    // Limita as dimensÃµes mÃ­nimas da caixa de corte
    const minDim = 40;
    width = Math.max(minDim, width);
    height = Math.max(minDim, height);
    
    // Limita para nÃ£o estourar a borda direita/inferior
    if (left + width > maxW) {
        width = maxW - left;
    }
    if (top + height > maxH) {
        height = maxH - top;
    }
    
    // Limita para nÃ£o estourar a esquerda/topo
    left = Math.max(0, Math.min(left, maxW - width));
    top = Math.max(0, Math.min(top, maxH - height));
    
    currentCropArea = { left, top, width, height };
    
    cropArea.style.left = left + 'px';
    cropArea.style.top = top + 'px';
    cropArea.style.width = width + 'px';
    cropArea.style.height = height + 'px';
}

function closeCrop() {
    isCroppingActive = false;
    if (cropOverlay) {
        cropOverlay.style.display = 'none';
    }
    activeCropHandle = null;
}

// Ouvintes para o overlay de corte
if (cropArea) {
    cropArea.addEventListener('mousedown', startCropDrag);
    cropArea.addEventListener('touchstart', startCropDrag, { passive: false });
}

window.addEventListener('mousemove', handleCropDrag);
window.addEventListener('touchmove', handleCropDrag, { passive: false });

window.addEventListener('mouseup', stopCropDrag);
window.addEventListener('touchend', stopCropDrag);

// Mapeia eventos de cantos das alÃ§as de corte
if (cropArea) {
    const handles = cropArea.querySelectorAll('.gemini-crop-handle');
    handles.forEach(handle => {
        handle.addEventListener('mousedown', (e) => {
            e.stopPropagation();
            startCropDrag(e, handle.getAttribute('data-handle'));
        });
        handle.addEventListener('touchstart', (e) => {
            e.stopPropagation();
            startCropDrag(e, handle.getAttribute('data-handle'));
        }, { passive: false });
    });
}

function startCropDrag(e, handle = 'move') {
    if (!isCroppingActive) return;
    e.preventDefault();
    
    activeCropHandle = handle;
    
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    
    cropDragStart = { x: clientX, y: clientY };
    cropStartRect = { ...currentCropArea };
}

function handleCropDrag(e) {
    if (!isCroppingActive || !activeCropHandle) return;
    e.preventDefault();
    
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    
    // VariaÃ§Ã£o de coordenadas em relaÃ§Ã£o ao ponto de inÃ­cio
    const dx = clientX - cropDragStart.x;
    const dy = clientY - cropDragStart.y;
    
    const start = cropStartRect;
    
    if (activeCropHandle === 'move') {
        // Arrastar caixa inteira
        updateCropArea(start.left + dx, start.top + dy, start.width, start.height);
    } else {
        // Redimensionar por uma das alÃ§as dos cantos
        let newLeft = start.left;
        let newTop = start.top;
        let newWidth = start.width;
        let newHeight = start.height;
        
        switch(activeCropHandle) {
            case 'tl': // Top Left
                newLeft = start.left + dx;
                newTop = start.top + dy;
                newWidth = start.width - dx;
                newHeight = start.height - dy;
                break;
            case 'tr': // Top Right
                newTop = start.top + dy;
                newWidth = start.width + dx;
                newHeight = start.height - dy;
                break;
            case 'bl': // Bottom Left
                newLeft = start.left + dx;
                newWidth = start.width - dx;
                newHeight = start.height + dy;
                break;
            case 'br': // Bottom Right
                newWidth = start.width + dx;
                newHeight = start.height + dy;
                break;
        }
        
        updateCropArea(newLeft, newTop, newWidth, newHeight);
    }
}

function stopCropDrag() {
    activeCropHandle = null;
}

// BotÃµes de AÃ§Ã£o do Crop
if (btnStudioCrop) {
    btnStudioCrop.addEventListener('click', () => {
        if (!isCroppingActive) {
            initCrop();
        } else {
            closeCrop();
        }
    });
}

if (btnCropDismiss) {
    btnCropDismiss.addEventListener('click', closeCrop);
}

if (btnCropApply) {
    btnCropApply.addEventListener('click', () => {
        if (!geminiOriginalImage || !isCroppingActive) return;
        
        showStudioLoading(true, "O Gemini estÃ¡ aplicando o seu corte...");
        
        setTimeout(() => {
            try {
                const canvasW = studioCanvas.clientWidth;
                const canvasH = studioCanvas.clientHeight;
                
                const origW = geminiOriginalImage.naturalWidth || geminiOriginalImage.width;
                const origH = geminiOriginalImage.naturalHeight || geminiOriginalImage.height;
                
                // Calcula as taxas de escala fÃ­sica vs visual
                const scaleX = origW / canvasW;
                const scaleY = origH / canvasH;
                
                // Mapeia coordenadas visuais da caixa de corte para pixels fÃ­sicos reais
                const realX = Math.round(currentCropArea.left * scaleX);
                const realY = Math.round(currentCropArea.top * scaleY);
                const realW = Math.round(currentCropArea.width * scaleX);
                const realH = Math.round(currentCropArea.height * scaleY);
                
                // ValidaÃ§Ãµes de limites
                if (realW <= 0 || realH <= 0) {
                    throw new Error("Ãrea de corte invÃ¡lida.");
                }
                
                // Cria canvas invisÃ­vel temporÃ¡rio para recortar
                const tempCanvas = document.createElement('canvas');
                tempCanvas.width = realW;
                tempCanvas.height = realH;
                const tempCtx = tempCanvas.getContext('2d');
                
                // Desenha a porÃ§Ã£o fÃ­sica recortada da imagem atual
                tempCtx.drawImage(geminiOriginalImage, realX, realY, realW, realH, 0, 0, realW, realH);
                
                const croppedDataUrl = tempCanvas.toDataURL('image/png');
                
                // Carrega a nova imagem recortada
                const newImg = new Image();
                newImg.onload = () => {
                    geminiOriginalImage = newImg;
                    
                    // Limpa filtros auxiliares de cor apÃ³s o recorte fÃ­sico
                    geminiFilters.sepia = 0;
                    geminiFilters.hueRotate = 0;
                    
                    redrawGeminiCanvas();
                    showStudioLoading(false);
                    closeCrop();
                    addChatMessage('assistant', "Pronto! Recortei a imagem focando na Ã¡rea selecionada conforme solicitado.");
                };
                newImg.src = croppedDataUrl;
                
            } catch(e) {
                console.error("Erro ao cortar a imagem:", e);
                showStudioLoading(false);
                closeCrop();
                addChatMessage('assistant', "Desculpe, ocorreu um erro ao recortar a imagem. Tente novamente.");
            }
        }, 800);
    });
}

