function getContentTypeByExtension(filename) {
    const ext = filename.split('.').pop().toLowerCase();
    switch(ext) {
        case 'png': return 'image/png';
        case 'jpg':
        case 'jpeg': return 'image/jpeg';
        case 'webp': return 'image/webp';
        case 'svg': return 'image/svg+xml';
        case 'pdf': return 'application/pdf';
        case 'eps': return 'application/postscript';
        case 'ai': return 'application/illustrator';
        default: return 'application/octet-stream';
    }
}

/** Gera tokens para busca (n-grams) a partir do nome e tags */
function generateSearchKeywords(filename, tags) {
    var tokens = new Set();
    function addGrams(str) {
        if(!str) return;
        var clean = str.toLowerCase().replace(/[^a-z0-9]/g, '');
        for (let i = 1; i <= clean.length; i++) {
            tokens.add(clean.substring(0, i));
        }
        var parts = str.toLowerCase().split(/[^a-z0-9]/);
        parts.forEach(p => {
            if(p.length > 2) tokens.add(p);
        });
    }
    addGrams(filename);
    if(tags && Array.isArray(tags)) {
        tags.forEach(addGrams);
    }
    return Array.from(tokens).slice(0, 30); // Limite do firebase
}

function extractTagsFromName(filename) {
    const nameWithoutExt = filename.substring(0, filename.lastIndexOf('.'));
    const parts = nameWithoutExt.toLowerCase().split(/[\s_\-]+/);
    return parts.filter(p => p.length > 2);
}

// Insere mídias (imagens, SVGs) na pulseira ativa
function insertMediaToCanvas(src) {
    disablePencilMode();
    const coords = getInsertionCoords();
    fabric.Image.fromURL(src, function(img) {
        const maxW = totalWidthPx * 0.6;
        const maxH = totalHeightPx * 0.8;
        let scale = 1;
        if (img.width > maxW || img.height > maxH) {
            scale = Math.min(maxW / img.width, maxH / img.height);
        }
        
        img.set({
            left: coords.left,
            top: coords.top,
            scaleX: scale,
            scaleY: scale,
            originX: 'center',
            originY: 'center',
            selectable: true
        });
        img.crossOrigin = 'anonymous';
        canvas.add(img);
        canvas.setActiveObject(img);
        canvas.requestRenderAll();
        saveHistory();
    }, { crossOrigin: 'anonymous' });
}

// Insere a primeira página de um PDF carregado do servidor como imagem
async function insertPdfPageToCanvas(pdfUrl) {
    alert("Carregando primeira página do PDF no Canvas...");
    try {
        const response = await fetch(pdfUrl);
        const arrayBuffer = await response.arrayBuffer();
        const typedarray = new Uint8Array(arrayBuffer);
        
        pdfjsLib.getDocument({ data: typedarray }).promise.then(function(pdf) {
            pdf.getPage(1).then(function(page) {
                const scale = 2.0;
                const viewport = page.getViewport({ scale: scale });
                
                const tempCanvas = document.createElement('canvas');
                tempCanvas.width = viewport.width;
                tempCanvas.height = viewport.height;
                const tempCtx = tempCanvas.getContext('2d');
                
                const renderContext = {
                    canvasContext: tempCtx,
                    viewport: viewport
                };
                
                page.render(renderContext).promise.then(function() {
                    const dataUrl = tempCanvas.toDataURL('image/png');
                    insertMediaToCanvas(dataUrl);
                });
            });
        }).catch(function(err) {
            console.error("Erro ao processar PDF:", err);
            alert("Erro ao renderizar primeira página do PDF no Canvas.");
        });
    } catch(err) {
        console.error("Falha ao buscar PDF:", err);
        alert("Falha ao carregar o arquivo PDF do servidor.");
    }
}

// Força o download de arquivos locais ou na nuvem contornando CORS
async function downloadOriginalFile(url, filename) {
    try {
        const response = await fetch(url);
        const blob = response.ok ? await response.blob() : null;
        if (!blob) throw new Error("Erro ao baixar arquivo do servidor");
        
        const blobUrl = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = blobUrl;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(blobUrl);
    } catch(err) {
        console.error("Falha no download:", err);
        window.open(url, '_blank');
    }
}

// Exclui mídias da biblioteca no Firestore e Storage

/** Escapa caracteres HTML para evitar XSS na renderizacao do painel de permissoes */
function escapeHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

