/** Papel do usuario atual: 'admin' | 'editor' | 'viewer' | null */
window.currentUserRole = null;

/** Cache de roles carregados para o painel de gerenciamento */
var _projectUserRoles = [];

/**
 * Carrega o papel (role) do usuario atual para o projeto ativo.
 * Em modo mock, assume 'admin'. Salva em window.currentUserRole.
 */
async function loadCurrentUserRole() {
    var projectId = window.currentProjectId || 'demo_project';
    var uid = currentUser ? currentUser.uid : 'mock_uid_123';

    if (isFirebaseMock) {
        // No modo demo, o usuario e sempre Admin
        window.currentUserRole = 'admin';
        applyRoleToUI();
        return;
    }

    try {
        var roleId = uid + '_' + projectId;
        var doc = await db.collection('userRoles').doc(roleId).get();
        if (doc.exists) {
            window.currentUserRole = doc.data().role || 'viewer';
        } else {
            // Primeiro acesso: cria como Admin (o criador do projeto)
            var roleData = {
                userId: uid,
                userEmail: currentUser.email || '',
                displayName: currentUser.displayName || currentUser.email || uid,
                role: 'admin',
                projectId: projectId,
                grantedBy: uid,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            };
            await db.collection('userRoles').doc(roleId).set(roleData);
            window.currentUserRole = 'admin';
        }
    } catch(err) {
        console.warn('Aviso: nao foi possivel carregar o papel do usuario:', err.message);
        window.currentUserRole = 'editor'; // fallback conservador
    }

    applyRoleToUI();
}

/** Aplica visibilidade de botoes baseado no papel do usuario */
function applyRoleToUI() {
    var role = window.currentUserRole;
    var isAdmin = role === 'admin';
    var canUpload = isAdmin || role === 'editor';

    // Botao de upload no header
    var uploadBtn = document.getElementById('btn-library-upload-toggle');
    if (uploadBtn) uploadBtn.style.display = canUpload ? 'flex' : 'none';

    // Botao de gerenciar permissoes (somente Admin)
    var permBtn = document.getElementById('btn-manage-permissions');
    if (permBtn) permBtn.style.display = isAdmin ? 'flex' : 'none';

    // Botao de nova categoria (Admin ou Editor)
    var newCatBtn = document.getElementById('btn-new-category');
    if (newCatBtn) newCatBtn.style.display = canUpload ? 'flex' : 'none';
}

/** Verifica se o usuario atual pode excluir um arquivo */
function canDeleteFile(file) {
    var role = window.currentUserRole;
    var uid = currentUser ? currentUser.uid : 'mock_uid_123';
    if (role === 'admin') return true;
    if (role === 'editor' && file.userId === uid) return true;
    return false;
}

/** Verifica se o usuario atual pode fazer upload */
function canUploadFiles() {
    var role = window.currentUserRole;
    return role === 'admin' || role === 'editor';
}

