/** Carrega a lista de roles do projeto para o painel */
async function loadPermissionsPanel() {
    var projectId = window.currentProjectId || 'demo_project';
    var listEl = document.getElementById('permissions-user-list');
    if (!listEl) return;

    listEl.innerHTML = '<div style="text-align:center;padding:30px;color:#475569;font-size:13px;">Carregando...</div>';

    try {
        if (isFirebaseMock) {
            var stored = JSON.parse(localStorage.getItem('mock_user_roles') || '[]');
            _projectUserRoles = stored.filter(function(r) { return r.projectId === projectId; });
            // Garantir que o usuario atual apareca como Admin
            var uid = currentUser ? currentUser.uid : 'mock_uid_123';
            var existing = _projectUserRoles.find(function(r) { return r.userId === uid; });
            if (!existing) {
                var selfRole = {
                    id: uid + '_' + projectId,
                    userId: uid,
                    userEmail: currentUser ? (currentUser.email || 'demo@arteideal.com.br') : 'demo@arteideal.com.br',
                    displayName: currentUser ? (currentUser.displayName || 'Designer Demo') : 'Designer Demo',
                    role: 'admin',
                    projectId: projectId,
                    grantedBy: uid,
                    createdAt: new Date().toISOString()
                };
                _projectUserRoles.unshift(selfRole);
            }
        } else {
            var snap = await db.collection('userRoles')
                .where('projectId', '==', projectId)
                .orderBy('createdAt', 'asc')
                .get();
            _projectUserRoles = snap.docs.map(function(d) { return Object.assign({ id: d.id }, d.data()); });
        }
        renderPermissionsUserList(_projectUserRoles);
    } catch(err) {
        listEl.innerHTML = '<div style="text-align:center;padding:30px;color:#f87171;font-size:13px;">Erro ao carregar: ' + err.message + '</div>';
    }
}

/** Renderiza a lista de usuarios no painel de permissoes */
function renderPermissionsUserList(roles) {
    var listEl = document.getElementById('permissions-user-list');
    if (!listEl) return;
    var currentUid = currentUser ? currentUser.uid : 'mock_uid_123';

    if (roles.length === 0) {
        listEl.innerHTML = '<div style="text-align:center;padding:40px;color:#475569;font-size:13px;">Nenhum usuario com acesso ainda.</div>';
        return;
    }

    listEl.innerHTML = '';
    roles.forEach(function(r) {
        var isYou = r.userId === currentUid;
        var initials = (r.displayName || r.userEmail || '?').substring(0, 2).toUpperCase();

        var row = document.createElement('div');
        row.className = 'permission-user-row';
        row.innerHTML =
            '<div class="permission-user-avatar">' + initials + '</div>' +
            '<div class="permission-user-info">' +
                '<div class="permission-user-name">' +
                    escapeHtml(r.displayName || r.userEmail || r.userId) +
                    (isYou ? '<span class="permission-you-tag">voce</span>' : '') +
                '</div>' +
                '<div class="permission-user-email">' + escapeHtml(r.userEmail || r.userId) + '</div>' +
            '</div>' +
            '<select class="permission-role-select" data-uid="' + r.userId + '">' +
                '<option value="admin"' + (r.role === 'admin' ? ' selected' : '') + '>Admin</option>' +
                '<option value="editor"' + (r.role === 'editor' ? ' selected' : '') + '>Editor</option>' +
                '<option value="viewer"' + (r.role === 'viewer' ? ' selected' : '') + '>Viewer</option>' +
            '</select>' +
            '<button class="permission-remove-btn" data-uid="' + r.userId + '" title="Remover acesso"' + (isYou ? ' disabled' : '') + '>&#x2715;</button>';

        // Listener do select de papel
        var sel = row.querySelector('.permission-role-select');
        sel.addEventListener('change', function() {
            updateUserRole(r.userId, this.value, r);
        });

        // Listener do botao de remover
        var removeBtn = row.querySelector('.permission-remove-btn');
        if (!isYou) {
            removeBtn.addEventListener('click', function() {
                removeUserAccess(r.userId, r.displayName || r.userEmail);
            });
        }

        listEl.appendChild(row);
    });
}

/** Atualiza o papel de um usuario */
async function updateUserRole(userId, newRole, roleData) {
    var projectId = window.currentProjectId || 'demo_project';
    try {
        if (isFirebaseMock) {
            var stored = JSON.parse(localStorage.getItem('mock_user_roles') || '[]');
            stored = stored.map(function(r) {
                return (r.userId === userId && r.projectId === projectId) ? Object.assign({}, r, { role: newRole }) : r;
            });
            localStorage.setItem('mock_user_roles', JSON.stringify(stored));
        } else {
            var roleId = userId + '_' + projectId;
            await db.collection('userRoles').doc(roleId).update({ role: newRole });
        }
        // Recarregar o grid da biblioteca se o usuario atual mudou
        if (userId === (currentUser ? currentUser.uid : 'mock_uid_123')) {
            window.currentUserRole = newRole;
            applyRoleToUI();
            loadLibraryFiles(true);
        }
    } catch(err) {
        alert('Erro ao atualizar papel: ' + err.message);
        loadPermissionsPanel(); // Reverter na UI
    }
}

/** Remove o acesso de um usuario ao projeto */
async function removeUserAccess(userId, displayName) {
    if (!confirm('Remover acesso de "' + (displayName || userId) + '"? Esta acao nao pode ser desfeita.')) return;
    var projectId = window.currentProjectId || 'demo_project';
    try {
        if (isFirebaseMock) {
            var stored = JSON.parse(localStorage.getItem('mock_user_roles') || '[]');
            stored = stored.filter(function(r) { return !(r.userId === userId && r.projectId === projectId); });
            localStorage.setItem('mock_user_roles', JSON.stringify(stored));
        } else {
            var roleId = userId + '_' + projectId;
            await db.collection('userRoles').doc(roleId).delete();
        }
        await loadPermissionsPanel();
    } catch(err) {
        alert('Erro ao remover acesso: ' + err.message);
    }
}

/** Adiciona um usuario por e-mail */
async function addUserByEmail(email, role) {
    if (!email || !email.trim()) { alert('Digite um e-mail valido.'); return; }
    email = email.trim().toLowerCase();
    var projectId = window.currentProjectId || 'demo_project';
    var currentUid = currentUser ? currentUser.uid : 'mock_uid_123';

    // Verificar se ja existe
    var already = _projectUserRoles.find(function(r) { return r.userEmail && r.userEmail.toLowerCase() === email; });
    if (already) { alert('Este usuario ja possui acesso a este projeto.'); return; }

    try {
        if (isFirebaseMock) {
            var newId = 'mock_' + Date.now();
            var newRole = {
                id: newId,
                userId: newId,
                userEmail: email,
                displayName: email.split('@')[0],
                role: role,
                projectId: projectId,
                grantedBy: currentUid,
                createdAt: new Date().toISOString()
            };
            var stored = JSON.parse(localStorage.getItem('mock_user_roles') || '[]');
            stored.push(newRole);
            localStorage.setItem('mock_user_roles', JSON.stringify(stored));
            await loadPermissionsPanel();
            document.getElementById('permissions-email-input').value = '';
        } else {
            // Buscar UID pelo e-mail nos userRoles de qualquer projeto
            var usersSnap = await db.collection('userRoles')
                .where('userEmail', '==', email)
                .limit(1)
                .get();

            var targetUid = null;
            var targetName = email.split('@')[0];
            if (!usersSnap.empty) {
                var found = usersSnap.docs[0].data();
                targetUid = found.userId;
                targetName = found.displayName || targetName;
            } else {
                alert('Usuario com e-mail "' + email + '" ainda nao tem conta no sistema. Ele precisa fazer login ao menos uma vez.');
                return;
            }

            var roleId = targetUid + '_' + projectId;
            await db.collection('userRoles').doc(roleId).set({
                userId: targetUid,
                userEmail: email,
                displayName: targetName,
                role: role,
                projectId: projectId,
                grantedBy: currentUid,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
            await loadPermissionsPanel();
            document.getElementById('permissions-email-input').value = '';
        }
    } catch(err) {
        alert('Erro ao adicionar usuario: ' + err.message);
    }
}

async function deleteLibraryFile(file) {
    try {
        if (isFirebaseMock) {
            let mockFiles = JSON.parse(localStorage.getItem('mock_files') || '[]');
            mockFiles = mockFiles.filter(x => x.fileId !== file.fileId);
            localStorage.setItem('mock_files', JSON.stringify(mockFiles));
            alert("Arquivo excluído com sucesso da biblioteca demo!");
            loadLibraryFiles(true);
        } else {
            await db.collection('files').doc(file.fileId).delete();
            if (storage && file.storagePath) {
                try {
                    await storage.ref().child(file.storagePath).delete();
                } catch(storageErr) {
                    console.warn("Aviso: Falha ao deletar no Storage:", storageErr.message);
                }
            }
            alert("Arquivo excluído com sucesso!");
            loadLibraryFiles(true);
        }
    } catch(err) {
        alert("Erro ao excluir arquivo: " + err.message);
    }
}


// =============================================
// SISTEMA DE CATEGORIAS DA BIBLIOTECA DE MIDIA
// =============================================

window.currentLibraryCategory = null;
var _libraryCategories = [];

async function loadCategories() {
    var projectId = window.currentProjectId || 'demo_project';
    try {
        if (isFirebaseMock) {
            var stored = JSON.parse(localStorage.getItem('mock_categories') || '[]');
            _libraryCategories = stored.filter(function(c) { return c.projectId === projectId; });
        } else {
            var snap = await db.collection('categories')
                .where('projectId', '==', projectId)
                .orderBy('createdAt', 'asc')
                .get();
            _libraryCategories = snap.docs.map(function(d) { return Object.assign({ id: d.id }, d.data()); });
        }
    } catch(err) {
        console.warn('Aviso ao carregar categorias:', err.message);
        _libraryCategories = [];
    }
    renderCategorySidebar(_libraryCategories);
    populateUploadCategorySelect(_libraryCategories);
}

function renderCategorySidebar(categories) {
    var list = document.getElementById('library-category-list');
    if (!list) return;

    var allActive = window.currentLibraryCategory === null ? ' active' : '';
    var uncatActive = window.currentLibraryCategory === '__uncategorized__' ? ' active' : '';
    list.innerHTML =
        '<div class="library-cat-item' + allActive + '" data-cat-id="__all__"><span>&#128450;&#65039;</span><span style="flex:1;">Todas</span></div>' +
        '<div class="library-cat-item' + uncatActive + '" data-cat-id="__uncategorized__"><span>&#128196;</span><span style="flex:1;">Sem Categoria</span></div>';

    function setupCategoryDropZone(el) {
        el.addEventListener('dragover', function(e) {
            e.preventDefault(); 
            if (el.dataset.catId !== '__all__') {
                el.classList.add('drag-over');
            }
        });
        el.addEventListener('dragleave', function(e) {
            el.classList.remove('drag-over');
        });
        el.addEventListener('drop', async function(e) {
            e.preventDefault();
            el.classList.remove('drag-over');
            
            const fileId = e.dataTransfer.getData('text/plain');
            if (!fileId) return;
            
            const targetCatId = el.dataset.catId;
            if (targetCatId === '__all__') return; // Nao pode soltar em Todas
            
            const finalCatId = targetCatId === '__uncategorized__' ? 'Sem Categoria' : targetCatId;
            
            const itemElem = document.querySelector(`.library-item[data-id="${fileId}"]`);
            if (itemElem && window.currentLibraryCategory && window.currentLibraryCategory !== '__all__') {
                itemElem.style.display = 'none'; // Some visualmente
            }
            
            try {
                if (isFirebaseMock) {
                    let mockFiles = JSON.parse(localStorage.getItem('mock_files') || '[]');
                    const idx = mockFiles.findIndex(f => f.fileId === fileId);
                    if (idx > -1) {
                        mockFiles[idx].categoryId = finalCatId;
                        mockFiles[idx].category = finalCatId;
                        localStorage.setItem('mock_files', JSON.stringify(mockFiles));
                    }
                } else {
                    await db.collection('files').doc(fileId).update({
                        categoryId: finalCatId,
                        category: finalCatId
                    });
                }
            } catch (err) {
                console.error("Erro ao mover arquivo", err);
                if (itemElem) itemElem.style.display = '';
                alert("Erro ao mover arquivo: " + err.message);
            }
        });
    }

    categories.forEach(function(cat) {
        var item = document.createElement('div');
        item.className = 'library-cat-item' + (window.currentLibraryCategory === cat.id ? ' active' : '');
        item.dataset.catId = cat.id;
        var safeName = String(cat.name).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        item.innerHTML =
            '<span>&#128193;</span>' +
            '<span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + safeName + '</span>' +
            '<button class="cat-delete" title="Excluir">&#10005;</button>';
        item.querySelector('.cat-delete').addEventListener('click', function(e) {
            e.stopPropagation();
            deleteCategoryById(cat.id);
        });
        item.addEventListener('click', function() { setActiveCategory(cat.id, cat.name); });
        setupCategoryDropZone(item);
        list.appendChild(item);
    });

    var elAll = list.querySelector('[data-cat-id="__all__"]');
    elAll.addEventListener('click', function() { setActiveCategory(null, null); });
    
    var elUncat = list.querySelector('[data-cat-id="__uncategorized__"]');
    elUncat.addEventListener('click', function() { setActiveCategory('__uncategorized__', 'Sem Categoria'); });
    setupCategoryDropZone(elUncat);
}

function setActiveCategory(categoryId, categoryName) {
    window.currentLibraryCategory = categoryId;
    var badge = document.getElementById('library-category-badge');
    if (badge) {
        if (categoryId && categoryId !== '__uncategorized__') {
            badge.textContent = categoryName || '';
            badge.style.display = 'inline-block';
        } else if (categoryId === '__uncategorized__') {
            badge.textContent = 'Sem Categoria';
            badge.style.display = 'inline-block';
        } else {
            badge.style.display = 'none';
        }
    }
    document.querySelectorAll('.library-cat-item').forEach(function(el) {
        var elId = el.dataset.catId;
        var isAct = (categoryId === null && elId === '__all__') ||
                    (categoryId === '__uncategorized__' && elId === '__uncategorized__') ||
                    (elId === categoryId);
        el.classList.toggle('active', isAct);
    });
    var sel = document.getElementById('upload-category-select');
    if (sel) sel.value = (categoryId && categoryId !== '__uncategorized__') ? categoryId : '';
    loadLibraryFiles(true);
}

function populateUploadCategorySelect(categories) {
    var sel = document.getElementById('upload-category-select');
    if (!sel) return;
    var prevVal = sel.value;
    sel.innerHTML = '<option value="">— Sem Categoria —</option>';
    categories.forEach(function(cat) {
        var opt = document.createElement('option');
        opt.value = cat.id;
        opt.textContent = cat.name;
        sel.appendChild(opt);
    });
    if (window.currentLibraryCategory && window.currentLibraryCategory !== '__uncategorized__') {
        sel.value = window.currentLibraryCategory;
    } else if (prevVal) {
        sel.value = prevVal;
    }
}

async function createCategory(name) {
    if (!name || !name.trim()) return;
    name = name.trim();
    var projectId = window.currentProjectId || 'demo_project';
    var userId = currentUser ? currentUser.uid : 'mock_uid_123';
    var catId = 'cat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
    try {
        if (isFirebaseMock) {
            var cats = JSON.parse(localStorage.getItem('mock_categories') || '[]');
            cats.push({ id: catId, name: name, projectId: projectId, userId: userId, createdAt: new Date().toISOString() });
            localStorage.setItem('mock_categories', JSON.stringify(cats));
        } else {
            await db.collection('categories').doc(catId).set({
                name: name,
                projectId: projectId,
                userId: userId,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        }
        await loadCategories();
        setActiveCategory(catId, name);
    } catch(err) {
        alert('Erro ao criar categoria: ' + err.message);
    }
}

async function deleteCategoryById(catId) {
    if (!confirm('Excluir esta categoria? Os arquivos ficarao sem categoria.')) return;
    try {
        if (isFirebaseMock) {
            var cats = JSON.parse(localStorage.getItem('mock_categories') || '[]');
            cats = cats.filter(function(c) { return c.id !== catId; });
            localStorage.setItem('mock_categories', JSON.stringify(cats));
            var files = JSON.parse(localStorage.getItem('mock_files') || '[]');
            files = files.map(function(f) {
                return f.categoryId === catId ? Object.assign({}, f, { categoryId: null, categoryName: null }) : f;
            });
            localStorage.setItem('mock_files', JSON.stringify(files));
        } else {
            await db.collection('categories').doc(catId).delete();
            var filesSnap = await db.collection('files').where('categoryId', '==', catId).get();
            if (!filesSnap.empty) {
                var batch = db.batch();
                filesSnap.forEach(function(doc) { batch.update(doc.ref, { categoryId: null, categoryName: null }); });
                await batch.commit();
            }
        }
        if (window.currentLibraryCategory === catId) setActiveCategory(null, null);
        await loadCategories();
    } catch(err) {
        alert('Erro ao excluir categoria: ' + err.message);
    }
}

// Envia arquivos para o Firebase Storage
async function uploadLibraryFiles(files) {
    if (!canUploadFiles()) {
        alert('Voce nao tem permissao para fazer upload de arquivos. Apenas Admin e Editor podem enviar arquivos.');
        return;
    }
    const progressContainer = document.getElementById('upload-progress-container');
    const progressFill = document.getElementById('upload-progress-fill');
    const progressPercent = document.getElementById('upload-progress-percent');
    const progressFilename = document.getElementById('upload-progress-filename');
    const allowedExtensions = ['png', 'jpg', 'jpeg', 'webp', 'svg', 'pdf', 'ai', 'eps', 'json'];
    
    const selCat = document.getElementById('upload-category-select');
    let targetCatId = 'Sem Categoria';
    if (selCat && selCat.value) {
        targetCatId = selCat.value;
    } else if (window.currentLibraryCategory && window.currentLibraryCategory !== '__all__' && window.currentLibraryCategory !== '__uncategorized__') {
        targetCatId = window.currentLibraryCategory;
    }
    
    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const ext = file.name.split('.').pop().toLowerCase();
        
        if (!allowedExtensions.includes(ext)) {
            alert(`O arquivo "${file.name}" tem um formato não suportado. Os formatos permitidos são: PNG, JPG, WEBP, SVG, PDF, AI, EPS, JSON.`);
            continue;
        }
        
        const maxSize = 20 * 1024 * 1024;
        if (file.size > maxSize) {
            alert(`O arquivo "${file.name}" excede o tamanho limite de 20MB.`);
            continue;
        }
        
        if (progressContainer) {
            progressContainer.style.display = 'block';
            progressFilename.textContent = file.name;
            progressFill.style.width = '0%';
            progressPercent.textContent = '0%';
        }
        
        const fileId = 'file_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
        const projectId = window.currentProjectId || 'demo_project';
        const userId = currentUser ? currentUser.uid : 'mock_uid_123';
        
        if (isFirebaseMock) {
            await new Promise((resolve) => {
                let progress = 0;
                const interval = setInterval(() => {
                    progress += 10;
                    if (progressFill) progressFill.style.width = `${progress}%`;
                    if (progressPercent) progressPercent.textContent = `${progress}%`;
                    if (progress >= 100) {
                        clearInterval(interval);
                        resolve();
                    }
                }, 100);
            });
            
            const reader = new FileReader();
            await new Promise((resolve) => {
                reader.onload = function(evt) {
                    const dataUrl = evt.target.result;
                    const mockFileDoc = {
                        fileId: fileId,
                        projectId: projectId,
                        userId: userId,
                        originalName: file.name,
                        storagePath: `projects/${projectId}/media/${userId}/${fileId}_${file.name}`,
                        originalUrl: dataUrl,
                        thumbnailUrl: ['pdf', 'ai', 'eps'].includes(ext) ? '' : dataUrl,
                        contentType: getContentTypeByExtension(file.name),
                        extension: ext,
                        size: file.size,
                        tags: extractTagsFromName(file.name),
                        category: targetCatId,
                        categoryId: targetCatId,
                        createdAt: new Date().toISOString()
                    };
                    
                    let mockFiles = localStorage.getItem('mock_files') ? JSON.parse(localStorage.getItem('mock_files')) : [];
                    mockFiles.push(mockFileDoc);
                    localStorage.setItem('mock_files', JSON.stringify(mockFiles));
                    resolve();
                };
                reader.readAsDataURL(file);
            });
            
            if (progressContainer) progressContainer.style.display = 'none';
            loadLibraryFiles(true);
        } else {
            try {
                const storagePath = `projects/${projectId}/media/${userId}/${fileId}_${file.name}`;
                const storageRef = storage.ref().child(storagePath);
                const uploadTask = storageRef.put(file);
                
                // Timeout de segurança de 15 segundos para falhas de CORS ou rede
                const timeoutId = setTimeout(() => {
                    uploadTask.cancel();
                }, 15000);
                
                await new Promise((resolve, reject) => {
                    uploadTask.on('state_changed', 
                        (snapshot) => {
                            const progress = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
                            if (progressFill) progressFill.style.width = `${progress}%`;
                            if (progressPercent) progressPercent.textContent = `${progress}%`;
                        }, 
                        (error) => {
                            clearTimeout(timeoutId);
                            if (error.code === 'storage/canceled') {
                                reject(new Error("Timeout no upload para o Storage. Verifique se o bucket do Storage possui a política CORS configurada para este domínio."));
                            } else {
                                reject(error);
                            }
                        }, 
                        async () => {
                            clearTimeout(timeoutId);
                            try {
                                const downloadUrl = await uploadTask.snapshot.ref.getDownloadURL();
                                const fileDoc = {
                                    fileId: fileId,
                                    projectId: projectId,
                                    userId: userId,
                                    originalName: file.name,
                                    storagePath: storagePath,
                                    originalUrl: downloadUrl,
                                    thumbnailUrl: "",
                                    contentType: file.type || getContentTypeByExtension(file.name),
                                    extension: ext,
                                    size: file.size,
                                    tags: extractTagsFromName(file.name),
                                    category: targetCatId,
                                    categoryId: targetCatId,
                                    searchKeywords: generateSearchKeywords(file.name, extractTagsFromName(file.name)),
                                    createdAt: firebase.firestore.FieldValue.serverTimestamp()
                                };
                                await db.collection('files').doc(fileId).set(fileDoc);
                                resolve();
                            } catch(err) {
                                reject(err);
                            }
                        }
                    );
                });
                if (progressContainer) progressContainer.style.display = 'none';
                loadLibraryFiles(true);
            } catch(err) {
                alert(`Erro ao enviar o arquivo "${file.name}": ` + err.message);
                if (progressContainer) progressContainer.style.display = 'none';
            }
        }
    }
}

// Carrega e lista arquivos indexados
let lastVisibleLibraryDoc = null;
async function loadLibraryFiles(resetPagination = true) {
    const grid = document.getElementById('library-grid');
    if (!grid) return;
    
    if (resetPagination) {
        grid.innerHTML = '<p style="text-align: center; color: #94a3b8; grid-column: 1/-1; padding: 20px;">Carregando mídias...</p>';
        lastVisibleLibraryDoc = null;
    }
    
    const filterType = document.getElementById('library-filter-type').value;
    const searchTerm = document.getElementById('library-search').value.toLowerCase().trim();
    
    try {
        let files = [];
        if (isFirebaseMock) {
            const mockFiles = localStorage.getItem('mock_files') ? JSON.parse(localStorage.getItem('mock_files')) : [];
            mockFiles.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
            let filtered = mockFiles.filter(f => f.projectId === (window.currentProjectId || 'demo_project'));
            
            if (window.currentLibraryCategory && window.currentLibraryCategory !== '__all__') {
                const targetCatId = window.currentLibraryCategory === '__uncategorized__' ? 'Sem Categoria' : window.currentLibraryCategory;
                filtered = filtered.filter(f => f.categoryId === targetCatId || f.category === targetCatId);
            }
            
            if (filterType === 'images') {
                filtered = filtered.filter(f => ['png', 'jpg', 'jpeg', 'webp'].includes(f.extension));
            } else if (filterType === 'vectors') {
                filtered = filtered.filter(f => ['svg', 'ai', 'eps'].includes(f.extension));
            } else if (filterType === 'pdfs') {
                filtered = filtered.filter(f => f.extension === 'pdf');
            }
            
            if (searchTerm) {
                filtered = filtered.filter(f => 
                    f.originalName.toLowerCase().includes(searchTerm) || 
                    (f.tags && f.tags.some(t => t.toLowerCase().includes(searchTerm)))
                );
            }
            files = filtered;
            document.getElementById('library-load-more-container').style.display = 'none';
        } else {
            let query = db.collection('files')
                .where('projectId', '==', window.currentProjectId || 'demo_project');
                
            if (window.currentLibraryCategory && window.currentLibraryCategory !== '__all__') {
                const targetCatId = window.currentLibraryCategory === '__uncategorized__' ? 'Sem Categoria' : window.currentLibraryCategory;
                query = query.where('categoryId', '==', targetCatId);
            }
                
            if (searchTerm) {
                query = query.where('searchKeywords', 'array-contains', searchTerm);
            }
            
            query = query.orderBy('createdAt', 'desc');
            
            if (lastVisibleLibraryDoc && !resetPagination) {
                query = query.startAfter(lastVisibleLibraryDoc);
            }
            
            query = query.limit(24);
            const snapshot = await query.get();
            
            if (snapshot.empty) {
                if (resetPagination) {
                    grid.innerHTML = '<p style="text-align: center; color: #94a3b8; grid-column: 1/-1; padding: 20px;">Nenhum arquivo na biblioteca do projeto ainda.</p>';
                }
                document.getElementById('library-load-more-container').style.display = 'none';
                return;
            }
            
            lastVisibleLibraryDoc = snapshot.docs[snapshot.docs.length - 1];
            snapshot.forEach(doc => {
                files.push({ id: doc.id, ...doc.data() });
            });
            
            if (filterType === 'images') {
                files = files.filter(f => ['png', 'jpg', 'jpeg', 'webp'].includes(f.extension));
            } else if (filterType === 'vectors') {
                files = files.filter(f => ['svg', 'ai', 'eps'].includes(f.extension));
            } else if (filterType === 'pdfs') {
                files = files.filter(f => f.extension === 'pdf');
            }
            
            if (searchTerm) {
                if (isFirebaseMock) {
                    files = files.filter(f => 
                        f.originalName.toLowerCase().includes(searchTerm) || 
                        (f.tags && f.tags.some(t => t.toLowerCase().includes(searchTerm)))
                    );
                }
            }
            
            if (snapshot.docs.length < 24) {
                document.getElementById('library-load-more-container').style.display = 'none';
            } else {
                document.getElementById('library-load-more-container').style.display = 'block';
            }
        }
        
        if (resetPagination) {
            grid.innerHTML = '';
        }
        renderLibraryItems(files);
    } catch(err) {
        console.error("Erro ao carregar mídias:", err);
        if (err.message && (err.message.includes("Firestore API has not been used") || err.message.includes("disabled") || err.message.includes("not been used in project"))) {
            isFirebaseMock = true;
            setupFirebaseMock();
            setTimeout(() => {
                loadLibraryFiles(resetPagination);
            }, 100);
            showFirebaseConfigWarning(
                "Banco de Dados Firestore Desativado",
                "O Cloud Firestore está desativado no console do Firebase do seu projeto. O aplicativo foi rebaixado temporariamente para o Modo Demo (Offline) para permitir uploads no navegador."
            );
            return;
        }
        grid.innerHTML = `<p style="text-align: center; color: #ef4444; grid-column: 1/-1; padding: 20px;">Erro ao carregar mídias: ${err.message}</p>`;
    }
}

function renderLibraryItems(files) {
    const grid = document.getElementById('library-grid');
    if (!grid) return;
    
    files.forEach(f => {
        const item = document.createElement('div');
        item.className = 'library-item';
        item.dataset.id = f.fileId;
        
        // Habilitar Drag para mover para outra categoria
        item.setAttribute('draggable', 'true');
        item.addEventListener('dragstart', function(e) {
            e.dataTransfer.setData('text/plain', f.fileId);
            e.dataTransfer.effectAllowed = 'move';
            item.classList.add('dragging');
        });
        item.addEventListener('dragend', function(e) {
            item.classList.remove('dragging');
        });
        
        const preview = document.createElement('div');
        preview.className = 'library-item-preview';
        
        const ext = f.extension.toLowerCase();
        const isImage = ['png', 'jpg', 'jpeg', 'webp', 'svg'].includes(ext);
        
        if (isImage || (ext === 'json' && f.thumbnailUrl)) {
            const img = document.createElement('img');
            img.src = f.thumbnailUrl || f.originalUrl;
            img.alt = f.originalName;
            img.loading = 'lazy';
            preview.appendChild(img);
        } else {
            const icon = document.createElement('span');
            icon.className = 'library-item-icon';
            if (ext === 'pdf') {
                icon.textContent = '📄';
            } else if (ext === 'json') {
                icon.textContent = '💾';
            } else if (ext === 'ai' || ext === 'eps' || ext === 'ps') {
                icon.textContent = '📐';
            } else {
                icon.textContent = '📦';
            }
            preview.appendChild(icon);
        }
        
        const info = document.createElement('div');
        info.className = 'library-item-info';
        
        const name = document.createElement('span');
        name.className = 'library-item-name';
        name.textContent = f.originalName;
        name.title = f.originalName;
        
        const meta = document.createElement('div');
        meta.className = 'library-item-meta';
        
        const badge = document.createElement('span');
        badge.className = 'library-item-badge';
        badge.textContent = ext;
        
        const sizeKB = (f.size / 1024).toFixed(1);
        const sizeStr = sizeKB > 1000 ? (sizeKB / 1024).toFixed(1) + ' MB' : sizeKB + ' KB';
        const size = document.createElement('span');
        size.textContent = sizeStr;
        
        meta.appendChild(badge);
        meta.appendChild(size);
        // Badge de categoria (se o arquivo tiver uma categoria)
        if (f.categoryName) {
            const catBadge = document.createElement('span');
            catBadge.className = 'library-cat-badge';
            catBadge.textContent = f.categoryName;
            catBadge.title = f.categoryName;
            const catRow = document.createElement('div');
            catRow.style.cssText = 'display:flex;align-items:center;gap:4px;margin-top:2px;';
            catRow.appendChild(catBadge);
            info.appendChild(name);
            info.appendChild(meta);
            info.appendChild(catRow);
        } else {
            info.appendChild(name);
            info.appendChild(meta);
        }
        
        const actions = document.createElement('div');
        actions.className = 'library-item-actions';
        
        const downloadBtn = document.createElement('button');
        downloadBtn.className = 'library-action-btn';
        downloadBtn.innerHTML = '📥';
        downloadBtn.title = 'Baixar original';
        downloadBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            downloadOriginalFile(f.originalUrl, f.originalName);
        });
        
        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'library-action-btn delete';
        deleteBtn.innerHTML = '&#x1F5D1;&#xFE0F;';
        deleteBtn.title = 'Excluir arquivo';
        // So mostrar o botao de excluir se o usuario tiver permissao
        if (!canDeleteFile(f)) {
            deleteBtn.style.display = 'none';
            deleteBtn.disabled = true;
        }
        deleteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            if (!canDeleteFile(f)) { alert('Voce nao tem permissao para excluir este arquivo.'); return; }
            if (confirm('Tem certeza que deseja excluir o arquivo "' + f.originalName + '" da biblioteca?')) {
                deleteLibraryFile(f);
            }
        });
        
        actions.appendChild(downloadBtn);
        actions.appendChild(deleteBtn);
        
        item.appendChild(preview);
        item.appendChild(info);
        item.appendChild(actions);
        
        item.addEventListener('click', () => {
            if (isImage) {
                // Abre o arquivo no AI Studio (mesmo comportamento do upload local)
                loadStudioImage(f.originalUrl);
                document.getElementById('library-overlay').style.display = 'none';
            } else if (ext === 'pdf') {
                insertPdfPageToCanvas(f.originalUrl);
                document.getElementById('library-overlay').style.display = 'none';
            } else if (ext === 'json') {
                if (confirm('Deseja carregar este projeto no editor? O projeto atual será substituído.')) {
                    fetch(f.originalUrl)
                        .then(res => res.json())
                        .then(data => {
                            if (typeof loadProjectData === 'function') {
                                loadProjectData(data);
                                document.getElementById('library-overlay').style.display = 'none';
                            } else {
                                alert('A função loadProjectData não está disponível.');
                            }
                        })
                        .catch(err => {
                            console.error('Erro ao carregar JSON:', err);
                            alert('Erro ao carregar projeto: ' + err.message);
                        });
                }
            } else {
                alert(`Arquivos no formato .${ext.toUpperCase()} não podem ser renderizados diretamente no Canvas. Você pode baixá-los para usá-los localmente em editores externos.`);
            }
        });
        
        grid.appendChild(item);
    });
}

