document.addEventListener('DOMContentLoaded', () => {
    // Upload de imagem já tratado acima (linha ~895)
    // Garante que o input é resetado após cada seleção para permitir re-selecionar o mesmo arquivo
    const inputImageUpload = document.getElementById('image-upload');
    if (inputImageUpload) {
        // O reset do value é feito no handler original; nada a fazer aqui
    }
    
    
    // 3. Filtros do Canvas Principal
    const selectFilter = document.getElementById('select-filter');
    if (selectFilter) {
        selectFilter.addEventListener('change', () => {
            const obj = canvas.getActiveObject();
            if (!obj || !obj.filters) return;
            
            const filterType = selectFilter.value;
            obj.filters = [];
            
            if (filterType === 'grayscale') {
                obj.filters.push(new fabric.Image.filters.Grayscale());
            } else if (filterType === 'sepia') {
                obj.filters.push(new fabric.Image.filters.Sepia());
            } else if (filterType === 'invert') {
                obj.filters.push(new fabric.Image.filters.Invert());
            }
            
            obj.applyFilters();
            canvas.requestRenderAll();
            if (typeof saveHistory === 'function') saveHistory();
        });
    }
    
    // 4. Exportar PNG/JPG
    function exportCanvas(type) {
        canvas.discardActiveObject();
        canvas.requestRenderAll();
        
        const dataURL = canvas.toDataURL({ format: type, quality: 0.95 });
        const link = document.createElement('a');
        link.href = dataURL;
        link.download = `arte-ideal-export.${type}`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }
    
    const btnExportPng = document.getElementById('btn-export-png');
    const btnExportJpg = document.getElementById('btn-export-jpg');
    
    if (btnExportPng) btnExportPng.addEventListener('click', () => exportCanvas('png'));
    if (btnExportJpg) btnExportJpg.addEventListener('click', () => exportCanvas('jpeg'));
});

