let db = null;
let auth = null;
let storage = null;
let isFirebaseMock = false;
let currentUser = null;

// Helper: Upload de Imagem para o Firebase Storage com Timeout de Segurança
async function uploadImageToFirebase(dataUrl) {
    if (isFirebaseMock || !currentUser || !storage) {
        return dataUrl;
    }
    
    // Promise de Timeout que rejeita após 4 segundos
    const timeoutPromise = new Promise((_, reject) => {
        setTimeout(() => reject(new Error("Timeout no upload para o Storage")), 4000);
    });
    
    try {
        const uploadPromise = (async () => {
            const res = await fetch(dataUrl);
            const blob = await res.blob();
            const filename = `gallery_${Date.now()}.png`;
            const fileRef = storage.ref().child(`users/${currentUser.uid}/gallery/${filename}`);
            const snapshot = await fileRef.put(blob);
            return await snapshot.ref.getDownloadURL();
        })();
        
        // Corrida entre o upload e o timeout de 4 segundos
        return await Promise.race([uploadPromise, timeoutPromise]);
    } catch (err) {
        console.error("Erro ou Timeout no upload para o Firebase Storage:", err);
        return dataUrl; // Retorna o base64 original como fallback seguro
    }
}

// Inicializa o Firebase (cai no Mock se nao configurado)
async function initFirebase() {
    try {
        const response = await fetch('firebase-config.json');
        if (!response.ok) throw new Error("firebase-config.json nao encontrado");
        const firebaseConfig = await response.json();
        
        firebase.initializeApp(firebaseConfig);
        db = firebase.firestore();
        auth = firebase.auth();
        storage = firebase.storage();
        isFirebaseMock = false;
        console.log("🔥 Firebase inicializado com sucesso!");
        
        // Atualiza a badge para online
        const statusBadge = document.getElementById('firebase-status');
        if (statusBadge) {
            statusBadge.textContent = 'online';
            statusBadge.className = 'status-badge status-online';
        }

        // Teste silencioso do Firestore para verificar se a API está ativa
        try {
            await db.collection('_conn_test').limit(1).get();
        } catch (connErr) {
            console.warn("Aviso de conexão do Firestore na inicialização:", connErr.message);
            if (connErr.message && (connErr.message.includes("Firestore API has not been used") || connErr.message.includes("disabled") || connErr.message.includes("not been used in project"))) {
                showFirebaseConfigWarning(
                    "Cloud Firestore Desativado",
                    "A API do Cloud Firestore está desativada no seu console do Firebase. O aplicativo mudou para o Modo Demo para permitir o funcionamento offline local."
                );
                isFirebaseMock = true;
                setupFirebaseMock();
                return;
            }
        }
    } catch (err) {
        console.warn("⚠️ Usando MOCK do Firebase (offline/demo):", err.message);
        isFirebaseMock = true;
        setupFirebaseMock();
    }
    setupAuthListeners();
}

