// Carrega os projetos salvos
async function loadUserProjectsList() {
    const listContainer = document.getElementById('projects-list-container');
    if (!listContainer) return;
    listContainer.innerHTML = '<p style="text-align: center; color: #94a3b8;">Carregando projetos...</p>';
    
    try {
        let projects = [];
        if (isFirebaseMock) {
            projects = localStorage.getItem('mock_db') ? JSON.parse(localStorage.getItem('mock_db')) : [];
        } else {
            const snap = await db.collection('users').doc(currentUser.uid).collection('projects').orderBy('updatedAt', 'desc').get();
            snap.forEach(doc => {
                projects.push({ id: doc.id, ...doc.data() });
            });
        }
        
        if (projects.length === 0) {
            listContainer.innerHTML = '<p style="text-align: center; color: #94a3b8; padding: 20px;">Nenhum projeto salvou na nuvem ainda.</p>';
            return;
        }
        
        listContainer.innerHTML = '';
        projects.forEach(p => {
            const item = document.createElement('div');
            item.style.display = 'flex';
            item.style.justifyContent = 'space-between';
            item.style.alignItems = 'center';
            item.style.padding = '12px 16px';
            item.style.background = 'rgba(255, 255, 255, 0.05)';
            item.style.borderRadius = '8px';
            item.style.border = '1px solid rgba(255, 255, 255, 0.08)';
            
            const info = document.createElement('div');
            info.style.display = 'flex';
            info.style.flexDirection = 'column';
            info.style.gap = '4px';
            
            const title = document.createElement('span');
            title.textContent = p.name;
            title.style.color = '#ffffff';
            title.style.fontWeight = '500';
            
            const dateStr = p.updatedAt ? (p.updatedAt.toDate ? p.updatedAt.toDate().toLocaleString() : new Date(p.updatedAt).toLocaleString()) : 'Data desconhecida';
            const subtitle = document.createElement('span');
            subtitle.textContent = `Salvo em: ${dateStr}`;
            subtitle.style.color = '#64748b';
            subtitle.style.fontSize = '12px';
            
            info.appendChild(title);
            info.appendChild(subtitle);
            
            const actions = document.createElement('div');
            actions.style.display = 'flex';
            actions.style.gap = '8px';
            
            const loadBtn = document.createElement('button');
            loadBtn.textContent = 'Carregar';
            loadBtn.className = 'btn btn-primary';
            loadBtn.style.padding = '6px 12px';
            loadBtn.style.fontSize = '13px';
            loadBtn.style.background = 'linear-gradient(135deg, #a855f7, #ec4899)';
            loadBtn.style.border = 'none';
            loadBtn.addEventListener('click', () => {
                loadProjectData(p);
                document.getElementById('projects-overlay').style.display = 'none';
            });
            
            const deleteBtn = document.createElement('button');
            deleteBtn.textContent = 'Excluir';
            deleteBtn.className = 'btn btn-outline';
            deleteBtn.style.padding = '6px 12px';
            deleteBtn.style.fontSize = '13px';
            deleteBtn.addEventListener('click', async () => {
                if (confirm(`Tem certeza que deseja excluir o projeto "${p.name}"?`)) {
                    try {
                        if (isFirebaseMock) {
                            let mockDb = JSON.parse(localStorage.getItem('mock_db'));
                            mockDb = mockDb.filter(x => x.id !== p.id);
                            localStorage.setItem('mock_db', JSON.stringify(mockDb));
                        } else {
                            await db.collection('users').doc(currentUser.uid).collection('projects').doc(p.id).delete();
                        }
                        loadUserProjectsList();
                    } catch (err) {
                        alert("Erro ao excluir: " + err.message);
                    }
                }
            });
            
            actions.appendChild(loadBtn);
            actions.appendChild(deleteBtn);
            item.appendChild(info);
            item.appendChild(actions);
            listContainer.appendChild(item);
        });
    } catch (err) {
        console.error("Erro ao carregar projetos:", err);
        if (err.message && (err.message.includes("Firestore API has not been used") || err.message.includes("disabled") || err.message.includes("not been used in project"))) {
            isFirebaseMock = true;
            setupFirebaseMock();
            setTimeout(() => {
                loadUserProjectsList();
            }, 100);
            showFirebaseConfigWarning(
                "Banco de Dados Firestore Desativado",
                "O Cloud Firestore está desativado no console do Firebase do seu projeto. O aplicativo mudou para o Modo Demo (Offline)."
            );
            return;
        }
        listContainer.innerHTML = `<p style="text-align: center; color: #ef4444; padding: 20px;">Erro ao carregar lista: ${err.message}</p>`;
    }
}

// Carrega os dados de um projeto
function loadProjectData(data) {
    try {
        let jsonToLoad = data.canvasData;
        if (typeof jsonToLoad === 'string') {
            jsonToLoad = JSON.parse(jsonToLoad);
        }
        
        pagesCount = data.pagesCount || 1;
        window.pageNames = data.pageNames || [];
        window.currentProjectId = data.id || 'demo_project';
        window.galleryImages = data.galleryImages || [];
        updateGalleryUI();
        
        if (data.colorPalette && Array.isArray(data.colorPalette)) {
            window.colorPalette = data.colorPalette;
            savePaletteToStorage();
            renderColorPalette();
        }
        
        if (pagesCount > 1) {
            canvas.setHeight((totalHeightPx * pagesCount) + (PAGE_GAP_PX * (pagesCount - 1)));
        } else {
            canvas.setHeight(totalHeightPx);
        }
        
        canvas.loadFromJSON(jsonToLoad, function() {
            const objs = canvas.getObjects();
            const loadedCutLine = objs.find(o => o.id === 'cutLine');
            const loadedSafeLine = objs.find(o => o.id === 'safeLine');
            
            if(loadedCutLine) Object.assign(cutLine, loadedCutLine);
            if(loadedSafeLine) Object.assign(safeLine, loadedSafeLine);
            
            updatePageNamesUI();
            selectPage(1);
            canvas.requestRenderAll();
            
            window.undoStack = [];
            saveHistory();
            alert("Projeto carregado com sucesso!");
        });
    } catch (err) {
        alert("Erro ao carregar os dados do projeto: " + err.message);
    }
}

